head.b:skin:
  :root{
    --bg:#0B0B10; --bg2:#101016; --bg3:#14141C; --panel:#14141C;
    --violet:#7C5CFF; --cyan:#22C3E6; --amber:#F5B83D; --pink:#FF6B9D; --green:#3ED598;
    --ink:#F7F3E8; --muted:#C9C4B4; --faint:#97917F;
    --glass:#14141C; --glass2:#1B1B24;
    --line:#26262F;
    --gold-grad:linear-gradient(120deg,#F2B544,#DD941F);
    --text-grad:linear-gradient(92deg,#F2B544 0%,#22C3E6 55%,#A78BFF 100%);
    --radius:20px;
    --btn-radius:14px;
    --panel-grad:linear-gradient(180deg,#1C1C26 0%,#14141C 100%);
    --panel-grad-soft:linear-gradient(180deg,#191922 0%,#12121A 100%);
    --panel-shadow:0 14px 34px rgba(0,0,0,.38), 0 2px 10px rgba(0,0,0,.28);
    --panel-shadow-lift:0 22px 48px rgba(0,0,0,.45), 0 4px 14px rgba(0,0,0,.3);
    --gold-text:#FFCE54;
    --gold-glow:0 10px 28px rgba(245,184,61,.35);
    --font-d:"Bricolage Grotesque",system-ui,sans-serif;
    --font-b:"Outfit",system-ui,sans-serif;
  }
  html{ scroll-behavior:smooth; }
  body{
    margin:0; background:linear-gradient(180deg,var(--bg) 0%,var(--bg2) 55%,var(--bg) 100%);
    color:var(--ink); font-family:var(--font-b); font-size:17px; line-height:1.6;
    overflow-x:hidden; -webkit-font-smoothing:antialiased;
  }
  #progressBar{ position:fixed; top:0; left:0; height:3px; width:0%; z-index:100; background:linear-gradient(90deg,#F2B544,#DD941F,#22C3E6); box-shadow:0 0 12px rgba(245,184,61,.7); }
  a:focus-visible, button:focus-visible, textarea:focus-visible{ outline:2px solid #F5B83D; outline-offset:3px; box-shadow:0 0 0 4px rgba(245,184,61,.22); }
  section{ scroll-margin-top:84px; }
  .page-sec{ min-height:60vh; }
  .wash{ position:absolute; inset:0; pointer-events:none; opacity:.5; }
  .live-tag{ display:inline-flex; align-items:center; gap:7px; font-size:12px; font-weight:800; letter-spacing:1.2px; text-transform:uppercase; color:#0B0B10; background:linear-gradient(120deg,#F2B544,#DD941F); padding:6px 12px; border-radius:999px; }
  .live-tag i{ width:8px;height:8px;border-radius:50%;background:#0B0B10; animation:pulse-dot 1.6s infinite; }
  .models-table{ width:100%; border-collapse:collapse; margin-top:26px; background:var(--panel-grad); border:1px solid var(--line); border-radius:16px; overflow:hidden; box-shadow:var(--panel-shadow); }
  .models-table th,.models-table td{ text-align:left; padding:14px 16px; border-bottom:1px solid var(--line); font-size:15px; }
  .models-table th{ font-family:var(--font-d); color:#FFCE54; background:#1B1B24; }
  .models-table tr:last-child td{ border-bottom:none; }
  .tut-acc{ margin-top:36px; display:flex; flex-direction:column; gap:12px; }
  .tut-acc .faq ol{ margin:0; padding:0 20px 19px 40px; list-style:decimal; color:var(--muted); font-size:15.5px; display:flex; flex-direction:column; gap:6px; }
  .req-grid,.legal-grid{ display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-top:36px; }
  .req-card,.legal-card{ background:var(--panel-grad); border:1px solid var(--line); border-radius:18px; padding:24px; box-shadow:var(--panel-shadow); }
  .req-card h3,.legal-card h3{ font-family:var(--font-d); font-size:19px; margin-bottom:10px; }
  .req-card li,.legal-card p,.legal-card li{ color:var(--muted); font-size:15px; }
  .req-card ul{ display:flex; flex-direction:column; gap:8px; }
  .changelog-list{ margin-top:36px; display:flex; flex-direction:column; gap:14px; }
  .change{ background:var(--panel-grad); border:1px solid var(--line); border-radius:18px; padding:22px 24px; display:grid; grid-template-columns:120px 1fr; gap:18px; box-shadow:var(--panel-shadow); }
  .change .ver-badge{ font-family:var(--font-d); font-weight:800; font-size:20px; color:#FFCE54; }
  .change .ver-badge span{ display:block; font-family:var(--font-b); font-weight:600; font-size:13px; color:var(--faint); margin-top:4px; }
  .change ul{ display:flex; flex-direction:column; gap:6px; color:var(--muted); font-size:15px; list-style:disc; padding-left:18px; }
  .activity-table{ width:100%; border-collapse:collapse; margin-top:16px; font-size:13.5px; }
  .activity-table th,.activity-table td{ text-align:left; padding:10px 12px; border-bottom:1px solid var(--line); }
  .activity-table th{ color:var(--faint); font-weight:700; }
  .st-ok{ color:#3ED598; font-weight:700; } .st-wait{ color:#FFCE54; font-weight:700; }
  @media (max-width:680px){ .req-grid,.legal-grid{ grid-template-columns:1fr; } .change{ grid-template-columns:1fr; } .activity-wrap{ overflow-x:auto; } }
  h1,h2,h3,h4,p,ul,ol,figure{ margin:0; }
  ul,ol{ padding:0; list-style:none; }
  a{ color:inherit; }
  img,svg{ display:block; }
  button{ font-family:inherit; cursor:pointer; }
  ::selection{ background:var(--violet); color:#fff; }

  /* ---------- living aurora background ---------- */
  .aurora{ position:fixed; inset:0; z-index:-2; overflow:hidden; pointer-events:none; }
  .blob{ position:absolute; border-radius:50%; filter:blur(90px); opacity:.5; will-change:transform; }
  .blob.b1{ width:560px;height:560px; background:radial-gradient(circle at 35% 35%, #7C5CFF, transparent 68%); top:-160px; left:-120px; animation:drift1 26s ease-in-out infinite alternate; }
  .blob.b2{ width:520px;height:520px; background:radial-gradient(circle at 60% 40%, #22C3E6, transparent 68%); top:12%; right:-200px; opacity:.38; animation:drift2 32s ease-in-out infinite alternate; }
  .blob.b3{ width:460px;height:460px; background:radial-gradient(circle at 50% 50%, #FF6B9D, transparent 68%); top:52%; left:-180px; opacity:.30; animation:drift1 38s ease-in-out infinite alternate-reverse; }
  .blob.b4{ width:480px;height:480px; background:radial-gradient(circle at 50% 50%, #F5B83D, transparent 68%); bottom:-200px; right:-120px; opacity:.26; animation:drift2 30s ease-in-out infinite alternate-reverse; }
  @keyframes drift1{ from{ transform:translate(0,0) scale(1);} to{ transform:translate(90px,60px) scale(1.14);} }
  @keyframes drift2{ from{ transform:translate(0,0) scale(1.08);} to{ transform:translate(-80px,90px) scale(.94);} }
  .grain{ position:fixed; inset:0; z-index:-1; pointer-events:none; opacity:.5;
    background-image:radial-gradient(rgba(255,255,255,.05) 1px, transparent 1px); background-size:26px 26px; }

  .wrap{ max-width:1180px; margin:0 auto; padding:0 20px; }
  section{ padding:88px 0 8px; position:relative; }

  /* ---------- nav ---------- */
  header.nav{
    position:sticky; top:0; z-index:60;
    backdrop-filter:blur(16px) saturate(1.4); -webkit-backdrop-filter:blur(16px) saturate(1.4);
    background:rgba(11,11,16,.78); border-bottom:1px solid var(--line);
  }
  .nav-in{ display:flex; align-items:center; gap:14px; padding:10px 0; flex-wrap:wrap; }
  .brand{ display:flex; align-items:center; gap:11px; text-decoration:none; font-family:var(--font-d); font-weight:800; font-size:21px; letter-spacing:.2px; padding:6px 4px; min-height:44px; flex:none; }
  .brand .grad{ background:var(--text-grad); -webkit-background-clip:text; background-clip:text; color:transparent; }
  /* ----- app pill tabs: dark track + sliding gold indicator ----- */
  .nav-links{
    position:relative; display:flex; gap:2px; margin-left:auto; flex-wrap:nowrap;
    background:#14141C; border:1px solid #26262F; border-radius:999px; padding:4px;
    box-shadow:inset 0 1px 0 rgba(255,255,255,.04), 0 10px 26px rgba(0,0,0,.32);
    max-width:100%;
  }
  .tab-indicator{
    position:absolute; top:4px; left:0; height:calc(100% - 8px); width:0;
    background:linear-gradient(120deg,#F2B544,#DD941F); border-radius:999px;
    box-shadow:0 6px 18px rgba(245,184,61,.45);
    transition:left .38s cubic-bezier(.3,.9,.25,1), width .38s cubic-bezier(.3,.9,.25,1), opacity .25s;
    opacity:0; pointer-events:none; z-index:0;
  }
  .nav-links a{
    position:relative; z-index:1; text-decoration:none; color:var(--muted); font-weight:600; font-size:14.5px;
    padding:9px 14px; border-radius:999px; min-height:38px; display:inline-flex; align-items:center; white-space:nowrap;
    transition:color .25s;
  }
  .nav-links a:hover{ color:#fff; }
  .nav-links a.active{ color:#241A02; font-weight:700; }
  .nav-cta{
    position:relative; overflow:hidden; margin-left:4px; text-decoration:none; font-weight:700; font-size:15px; color:#241A02;
    background:var(--gold-grad); padding:12px 20px; border-radius:var(--btn-radius); min-height:48px; flex:none;
    display:inline-flex; align-items:center; box-shadow:var(--gold-glow);
    transition:transform .25s, box-shadow .25s;
  }
  .nav-cta:hover{ transform:translateY(-2px); box-shadow:0 14px 34px rgba(245,184,61,.45); }
  .nav-cta::after{
    content:""; position:absolute; top:0; left:-70%; width:45%; height:100%;
    background:linear-gradient(105deg,transparent,rgba(255,255,255,.55),transparent);
    transform:skewX(-20deg); animation:shine 3.4s ease-in-out infinite;
  }

  /* logo mark */
  .logo-mark{ flex:none; filter:drop-shadow(0 6px 18px rgba(245,184,61,.35)); }

  /* ---------- hero ---------- */
  .hero{ padding:64px 0 30px; }
  .hero-grid{ display:grid; grid-template-columns:1.05fr .95fr; gap:48px; align-items:center; }
  .pill{
    display:inline-flex; align-items:center; gap:8px; font-size:13.5px; font-weight:600; color:var(--ink);
    background:var(--panel-grad); border:1px solid var(--line); border-radius:999px; padding:7px 14px; box-shadow:var(--panel-shadow);
  }
  .pill .dot{ width:8px;height:8px;border-radius:50%; background:var(--green); box-shadow:0 0 0 0 rgba(62,213,152,.6); animation:pulse-dot 2s infinite; }
  @keyframes pulse-dot{ 0%{ box-shadow:0 0 0 0 rgba(62,213,152,.55);} 70%{ box-shadow:0 0 0 9px rgba(62,213,152,0);} 100%{ box-shadow:0 0 0 0 rgba(62,213,152,0);} }
  h1{
    font-family:var(--font-d); font-weight:800; line-height:1.04; letter-spacing:-.5px;
    font-size:clamp(40px,6.2vw,66px); margin-top:20px;
  }
  h1 .grad{ background:var(--text-grad); -webkit-background-clip:text; background-clip:text; color:transparent; }
  .hero-sub{ color:var(--muted); font-size:19px; max-width:34em; margin-top:18px; }
  .hero-cta{ display:flex; gap:14px; flex-wrap:wrap; margin-top:30px; align-items:center; }
  .btn-gold{
    position:relative; overflow:hidden; text-decoration:none; color:#241A02; font-weight:700; font-size:16.5px;
    background:var(--gold-grad); padding:14px 26px; border-radius:var(--btn-radius); min-height:52px; border:none;
    display:inline-flex; align-items:center; justify-content:center; gap:10px; box-shadow:var(--gold-glow);
    transition:transform .25s, box-shadow .25s;
  }
  .btn-gold:hover{ transform:translateY(-3px); box-shadow:0 18px 42px rgba(245,184,61,.5); }
  .btn-gold::after{
    content:""; position:absolute; top:0; left:-70%; width:45%; height:100%;
    background:linear-gradient(105deg,transparent,rgba(255,255,255,.55),transparent);
    transform:skewX(-20deg); animation:shine 3.4s ease-in-out infinite;
  }
  @keyframes shine{ 0%,55%{ left:-70%; } 85%,100%{ left:130%; } }
  .btn-ghost{
    text-decoration:none; font-weight:700; color:var(--gold-text); padding:14px 22px; min-height:52px;
    display:inline-flex; align-items:center; justify-content:center; gap:9px; border-radius:var(--btn-radius);
    background:var(--panel-grad); border:1px solid var(--line); box-shadow:var(--panel-shadow);
    transition:border-color .25s, transform .25s, box-shadow .25s;
  }
  .btn-ghost:hover{ border-color:rgba(245,184,61,.55); transform:translateY(-3px); box-shadow:var(--panel-shadow-lift); }
  .hero-note{ color:var(--faint); font-size:14px; margin-top:14px; }

  /* ---------- mini demo (hero) ---------- */
  .mini-shell{
    background:linear-gradient(160deg, rgba(255,255,255,.10), rgba(255,255,255,.03));
    border:1px solid var(--line); border-radius:26px; padding:14px;
    box-shadow:0 30px 80px rgba(0,0,0,.45), 0 0 0 1px rgba(124,92,255,.12), 0 24px 70px -30px rgba(124,92,255,.55);
  }
  .mini-bar{ display:flex; align-items:center; gap:7px; padding:2px 6px 12px; }
  .mini-bar i{ width:11px;height:11px;border-radius:50%; display:block; }
  .mini-bar .t{ margin-left:8px; font-size:13px; color:var(--muted); font-weight:600; letter-spacing:.4px; }
  .mini-stage{ position:relative; height:308px; border-radius:18px; overflow:hidden; background:radial-gradient(120% 130% at 20% 0%, #241B52 0%, #14102E 55%, #0D0B1E 100%); }
  .scene{ position:absolute; inset:0; padding:22px; opacity:0; transform:translateY(14px) scale(.985); transition:opacity .55s ease, transform .55s ease; pointer-events:none; }
  .scene.on{ opacity:1; transform:none; pointer-events:auto; }
  .scene-splash{ display:flex; flex-direction:column; align-items:center; justify-content:center; gap:14px; text-align:center; }
  .splash-logo{ animation:logo-pulse 1.6s ease-in-out infinite; }
  @keyframes logo-pulse{ 0%,100%{ transform:scale(1); filter:drop-shadow(0 0 0 rgba(245,184,61,0)); } 50%{ transform:scale(1.07); filter:drop-shadow(0 0 22px rgba(245,184,61,.55)); } }
  .scene-splash .nm{ font-family:var(--font-d); font-weight:800; font-size:24px; }
  .scene-splash .st{ color:var(--muted); font-size:13.5px; min-height:20px; }
  .loadbar{ width:190px; height:6px; border-radius:99px; background:rgba(255,255,255,.12); overflow:hidden; }
  .loadbar i{ display:block; height:100%; width:0; border-radius:99px; background:var(--gold-grad); }
  .scene.on .loadbar i{ animation:load 2.6s ease forwards; }
  @keyframes load{ from{ width:4%; } to{ width:100%; } }
  .portal-card{
    max-width:300px; margin:14px auto 0; background:rgba(16,13,36,.82); border:1px solid var(--line);
    border-radius:18px; padding:20px; backdrop-filter:blur(8px); box-shadow:0 24px 50px rgba(0,0,0,.5);
  }
  .portal-card h4{ font-family:var(--font-d); font-size:18px; text-align:center; }
  .portal-card .sub{ text-align:center; color:var(--muted); font-size:13px; margin-top:3px; }
  .fake-input{
    margin-top:14px; background:rgba(255,255,255,.07); border:1px solid var(--line); border-radius:10px;
    padding:10px 12px; font-size:13.5px; color:var(--ink); letter-spacing:1.5px; min-height:20px;
    display:flex; justify-content:space-between; align-items:center;
  }
  .fake-input .caret{ width:2px; height:16px; background:var(--amber); animation:blink 1s steps(1) infinite; }
  @keyframes blink{ 50%{ opacity:0; } }
  .fake-btn{ margin-top:12px; text-align:center; background:var(--gold-grad); color:#241A02; font-weight:700; font-size:14.5px; padding:12px; border-radius:var(--btn-radius); box-shadow:var(--gold-glow); min-height:46px; display:flex; align-items:center; justify-content:center; }
  .blur-bg{ position:absolute; inset:0; padding:22px; filter:blur(5px) brightness(.75); opacity:.85; }
  .tile-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:12px; }
  .tile{
    border-radius:14px; padding:12px; background:rgba(255,255,255,.06); border:1px solid var(--line);
    min-height:118px; display:flex; flex-direction:column; gap:8px;
  }
  .tile .thumb{ height:44px; border-radius:9px; }
  .tile .cap{ font-size:12px; color:var(--muted); font-weight:600; line-height:1.35; }
  .tile .bar{ height:5px; border-radius:99px; background:rgba(255,255,255,.12); overflow:hidden; margin-top:auto; }
  .tile .bar i{ display:block; height:100%; width:0; border-radius:99px; }
  .tile .stat{ font-size:11.5px; font-weight:700; letter-spacing:.4px; text-transform:uppercase; }
  .scene-tiles .tile .bar i{ animation:tilefill 2.8s ease forwards; }
  @keyframes tilefill{ 0%{ width:6%; } 55%{ width:64%; } 100%{ width:100%; } }
  .saved-row{ display:flex; flex-direction:column; gap:10px; max-width:330px; margin:16px auto 0; }
  .saved-item{
    display:flex; align-items:center; gap:12px; background:rgba(255,255,255,.06); border:1px solid var(--line);
    border-radius:13px; padding:12px 14px; font-size:14.5px; font-weight:600;
    opacity:0; transform:translateX(-14px);
  }
  .scene.on .saved-item{ animation:save-in .5s ease forwards; }
  .scene.on .saved-item:nth-child(2){ animation-delay:.45s; }
  .scene.on .saved-item:nth-child(3){ animation-delay:.9s; }
  @keyframes save-in{ to{ opacity:1; transform:none; } }
  .tick{ width:24px;height:24px; flex:none; border-radius:50%; background:rgba(62,213,152,.18); display:grid; place-items:center; }
  .mini-dots{ display:flex; gap:7px; justify-content:center; padding-top:12px; }
  .mini-dots i{ width:7px;height:7px;border-radius:50%; background:rgba(255,255,255,.22); transition:background .3s, transform .3s; }
  .mini-dots i.on{ background:var(--amber); transform:scale(1.35); }
  .mini-cap{ text-align:center; color:var(--faint); font-size:13px; margin-top:10px; }

  /* ---------- marquee ---------- */
  .marquee{ margin-top:64px; overflow:hidden; padding:15px 0; background:var(--panel-grad-soft); border-radius:18px; box-shadow:var(--panel-shadow);
    -webkit-mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent); mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent); }
  .marquee-track{ display:flex; gap:0; width:max-content; animation:marq 30s linear infinite; }
  .marquee:hover .marquee-track{ animation-play-state:paused; }
  @keyframes marq{ to{ transform:translateX(-50%); } }
  .marquee span{ font-family:var(--font-d); font-weight:700; font-size:16px; letter-spacing:1.6px; text-transform:uppercase; padding:0 22px; white-space:nowrap; color:var(--muted); }
  .marquee b{ padding:0 2px; }
  .c-v{ color:#A78BFF; } .c-c{ color:#5ED6F2; } .c-a{ color:#FFCE54; } .c-p{ color:#FF8FB5; } .c-g{ color:#6FE3B4; }

  /* ---------- section heads ---------- */
  .kicker{ display:inline-flex; align-items:center; gap:8px; font-size:13px; font-weight:700; letter-spacing:2.2px; text-transform:uppercase; color:#FFCE54 !important; }
  .kicker::before{ content:""; width:26px; height:2px; border-radius:2px; background:linear-gradient(120deg,#F2B544,#DD941F); box-shadow:0 0 10px rgba(245,184,61,.6); }
  h2{ font-family:var(--font-d); font-weight:800; font-size:clamp(29px,4.4vw,44px); line-height:1.12; letter-spacing:-.3px; margin-top:12px; }
  h2 .grad{ background:var(--text-grad); -webkit-background-clip:text; background-clip:text; color:transparent; }
  .sec-sub{ color:var(--muted); max-width:44em; margin-top:12px; font-size:17.5px; }

  /* ---------- reveal ---------- */
  .rv{ opacity:0; transform:translateY(26px); transition:opacity .7s ease, transform .7s cubic-bezier(.2,.7,.2,1); }
  .rv.in{ opacity:1; transform:none; }
  .rv.d1{ transition-delay:.08s; } .rv.d2{ transition-delay:.16s; } .rv.d3{ transition-delay:.24s; }
  .rv.d4{ transition-delay:.32s; } .rv.d5{ transition-delay:.4s; }

  /* ---------- stats ---------- */
  .stats{ display:grid; grid-template-columns:repeat(4,1fr); gap:16px; margin-top:44px; }
  .stat{
    background:var(--panel-grad); border:1px solid var(--line); border-radius:var(--radius); padding:24px 22px;
    position:relative; overflow:hidden; box-shadow:var(--panel-shadow);
  }
  .stat::before{ content:""; position:absolute; inset:0 0 auto 0; height:3px; background:var(--ac,var(--violet)); opacity:.9; }
  .stat .num{ font-family:var(--font-d); font-weight:800; font-size:clamp(30px,3.6vw,42px); line-height:1; }
  .stat .lbl{ color:var(--muted); font-size:14.5px; margin-top:8px; font-weight:600; }

  /* ---------- features ---------- */
  .feat-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:18px; margin-top:42px; }
  .feat{
    background:var(--panel-grad); border:1px solid var(--line); border-radius:var(--radius); padding:26px 24px; box-shadow:var(--panel-shadow);
    transition:transform .35s cubic-bezier(.2,.7,.2,1), box-shadow .35s, border-color .35s;
  }
  .feat:hover{ transform:translateY(-7px); border-color:color-mix(in srgb, var(--ac) 55%, transparent); box-shadow:var(--panel-shadow-lift), 0 24px 50px -18px color-mix(in srgb, var(--ac) 65%, transparent); }
  .feat .ic{
    width:52px; height:52px; border-radius:15px; display:grid; place-items:center;
    background:color-mix(in srgb, var(--ac) 16%, transparent); border:1px solid color-mix(in srgb, var(--ac) 40%, transparent);
    color:var(--ac);
  }
  .feat h3{ font-family:var(--font-d); font-size:20px; margin-top:16px; }
  .feat p{ color:var(--muted); font-size:15.5px; margin-top:7px; }

  /* ---------- steps ---------- */
  .steps{ display:grid; grid-template-columns:repeat(4,1fr); gap:18px; margin-top:44px; counter-reset:step; }
  .step{ position:relative; background:var(--panel-grad); border:1px solid var(--line); border-radius:var(--radius); padding:26px 22px; box-shadow:var(--panel-shadow); }
  .step .n{
    font-family:var(--font-d); font-weight:800; font-size:15px; width:38px; height:38px; border-radius:50%;
    display:grid; place-items:center; color:#14102A; background:var(--ac);
    box-shadow:0 8px 22px -6px var(--ac);
  }
  .step h3{ font-family:var(--font-d); font-size:18.5px; margin-top:15px; }
  .step p{ color:var(--muted); font-size:15px; margin-top:6px; }
  .step:not(:last-child)::after{
    content:""; position:absolute; top:44px; right:-13px; width:8px; height:8px; border-radius:50%;
    background:var(--ac); opacity:.7; z-index:2;
  }
  /* ---------- interactive demo ---------- */
  .demo-shell{
    margin-top:42px; border-radius:26px; padding:22px;
    background:linear-gradient(180deg,#1E1B2E 0%,#14141C 55%,#101019 100%);
    border:1px solid var(--line); box-shadow:var(--panel-shadow-lift);
  }
  .demo-top{ display:flex; align-items:center; gap:12px; flex-wrap:wrap; }
  .demo-top .ttl{ font-family:var(--font-d); font-weight:800; font-size:19px; }
  .credits-chip{
    margin-left:auto; display:inline-flex; align-items:center; gap:9px; font-weight:700; font-size:15px;
    background:rgba(245,184,61,.13); border:1px solid rgba(245,184,61,.45); color:#FFCE54;
    padding:8px 15px; border-radius:999px;
  }
  .credits-chip b{ font-family:var(--font-d); font-size:18px; color:#fff; min-width:3ch; text-align:right; }
  .demo-prompts{
    width:100%; margin-top:16px; background:#0F0F16; border:1px solid var(--line); border-radius:var(--btn-radius);
    color:var(--ink); font-family:var(--font-b); font-size:15px; line-height:1.55; padding:14px 16px; min-height:96px; resize:vertical;
    box-shadow:inset 0 2px 8px rgba(0,0,0,.4);
  }
  .demo-prompts:focus{ outline:2px solid #F5B83D; outline-offset:2px; border-color:rgba(245,184,61,.6); }
  .demo-actions{ display:flex; gap:12px; align-items:center; margin-top:14px; flex-wrap:wrap; }
  .btn-gen{
    position:relative; overflow:hidden; border:none; font-weight:700; font-size:16px; padding:14px 26px; border-radius:var(--btn-radius); min-height:52px;
    background:var(--gold-grad); color:#241A02;
    box-shadow:var(--gold-glow); transition:transform .25s, box-shadow .25s, opacity .25s;
    display:inline-flex; align-items:center; justify-content:center; gap:9px;
  }
  .btn-gen::after{
    content:""; position:absolute; top:0; left:-70%; width:45%; height:100%;
    background:linear-gradient(105deg,transparent,rgba(255,255,255,.55),transparent);
    transform:skewX(-20deg); animation:shine 3.4s ease-in-out infinite;
  }
  .btn-gen:hover:not(:disabled){ transform:translateY(-2px); box-shadow:0 16px 38px rgba(245,184,61,.5); }
  .btn-gen:disabled{ opacity:.55; cursor:wait; }
  .btn-reset{
    background:var(--panel-grad); color:var(--gold-text); border:1px solid var(--line); font-weight:700; font-size:15px;
    padding:14px 22px; border-radius:var(--btn-radius); min-height:52px; box-shadow:var(--panel-shadow); transition:border-color .25s, transform .25s;
    display:inline-flex; align-items:center; justify-content:center;
  }
  .btn-reset:hover{ border-color:rgba(245,184,61,.55); transform:translateY(-2px); }
  .demo-status{ color:var(--muted); font-size:14.5px; font-weight:600; }
  .demo-tiles{ display:grid; grid-template-columns:repeat(3,1fr); gap:14px; margin-top:18px; }
  .dtile{ border-radius:16px; padding:16px; background:var(--panel-grad-soft); border:1px solid var(--line); min-height:150px; display:flex; flex-direction:column; gap:9px; transition:border-color .3s; box-shadow:var(--panel-shadow); }
  .dtile .thumb{ height:52px; border-radius:10px; position:relative; overflow:hidden; }
  .dtile .thumb::after{ content:""; position:absolute; inset:0; background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.35) 50%,transparent 70%); transform:translateX(-120%); }
  .dtile.working .thumb::after{ animation:shimmer 1.4s ease-in-out infinite; }
  @keyframes shimmer{ to{ transform:translateX(120%); } }
  .dtile .cap{ font-size:13.5px; color:var(--muted); line-height:1.45; }
  .dtile .bar{ height:6px; border-radius:99px; background:rgba(255,255,255,.12); overflow:hidden; margin-top:auto; }
  .dtile .bar i{ display:block; height:100%; width:0; border-radius:99px; transition:width .3s ease; }
  .dtile .stat{ font-size:12px; font-weight:700; letter-spacing:1.1px; text-transform:uppercase; display:flex; align-items:center; gap:7px; }
  .dtile.done{ border-color:rgba(62,213,152,.55); }

  /* ---------- pricing ---------- */
  .price-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:18px; margin-top:44px; align-items:stretch; }
  .price{
    background:var(--panel-grad); border:1px solid var(--line); border-radius:24px; padding:30px 26px; box-shadow:var(--panel-shadow);
    display:flex; flex-direction:column; transition:transform .35s, box-shadow .35s;
  }
  .price:hover{ transform:translateY(-6px); box-shadow:var(--panel-shadow-lift); }
  .price.best{
    background:linear-gradient(170deg, rgba(124,92,255,.20), rgba(255,255,255,.05) 55%, rgba(245,184,61,.14));
    border:1.5px solid transparent;
    background-clip:padding-box; position:relative;
    box-shadow:0 30px 70px -20px rgba(124,92,255,.55);
  }
  .price.best::before{
    content:""; position:absolute; inset:-1.5px; border-radius:24px; padding:1.5px; z-index:-1;
    background:linear-gradient(140deg,#7C5CFF,#22C3E6,#F5B83D);
    -webkit-mask:linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite:xor; mask-composite:exclude;
  }
  .best-tag{
    align-self:flex-start; font-size:12.5px; font-weight:800; letter-spacing:1.4px; text-transform:uppercase;
    background:var(--text-grad); -webkit-background-clip:text; background-clip:text; color:transparent;
    border:1px solid rgba(255,255,255,.25); padding:5px 11px; border-radius:999px; margin-bottom:14px;
  }
  .price h3{ font-family:var(--font-d); font-size:21px; }
  .price .amt{ font-family:var(--font-d); font-weight:800; font-size:44px; line-height:1.05; margin-top:12px; }
  .price .amt small{ font-size:16px; color:var(--muted); font-weight:600; font-family:var(--font-b); }
  .price .per{ color:var(--muted); font-size:14.5px; margin-top:2px; }
  .price ul{ margin-top:20px; display:flex; flex-direction:column; gap:10px; flex:1; }
  .price li{ display:flex; gap:10px; font-size:15px; color:var(--muted); }
  .price li svg{ flex:none; margin-top:3px; }
  .price .pcta{
    position:relative; overflow:hidden; margin-top:24px; text-align:center; text-decoration:none; font-weight:700; font-size:15.5px; min-height:52px;
    display:flex; align-items:center; justify-content:center; border-radius:var(--btn-radius); padding:14px 22px;
    background:var(--panel-grad); border:1px solid var(--line); color:var(--gold-text); box-shadow:var(--panel-shadow); transition:transform .25s, border-color .25s;
  }
  .price .pcta:hover{ transform:translateY(-2px); border-color:rgba(245,184,61,.55); }
  .price.best .pcta{ background:var(--gold-grad); color:#241A02; border:none; box-shadow:var(--gold-glow); }
  .price.best .pcta::after{
    content:""; position:absolute; top:0; left:-70%; width:45%; height:100%;
    background:linear-gradient(105deg,transparent,rgba(255,255,255,.55),transparent);
    transform:skewX(-20deg); animation:shine 3.4s ease-in-out infinite;
  }

  /* ---------- tutorials ---------- */
  .tut-list{ display:grid; grid-template-columns:1fr 1fr; gap:14px; margin-top:42px; }
  .tut{
    display:flex; align-items:center; gap:16px; text-decoration:none;
    background:var(--panel-grad); border:1px solid var(--line); border-radius:18px; padding:18px 20px; min-height:76px; box-shadow:var(--panel-shadow);
    transition:transform .3s, border-color .3s, background .3s;
  }
  .tut:hover{ transform:translateX(6px); background:var(--glass2); border-color:color-mix(in srgb, var(--ac) 55%, transparent); }
  .tut .play{
    width:46px; height:46px; flex:none; border-radius:50%; display:grid; place-items:center; color:#14102A;
    background:var(--ac); box-shadow:0 8px 20px -6px var(--ac);
  }
  .tut .tt{ font-family:var(--font-d); font-weight:700; font-size:17px; }
  .tut .td{ color:var(--muted); font-size:14px; }
  .tut .arr{ margin-left:auto; color:var(--faint); flex:none; transition:transform .3s, color .3s; }
  .tut:hover .arr{ transform:translateX(4px); color:#fff; }

  /* ---------- faq ---------- */
  .faq-list{ margin-top:38px; display:flex; flex-direction:column; gap:12px; max-width:820px; }
  .faq{ background:var(--panel-grad); border:1px solid var(--line); border-radius:16px; overflow:hidden; box-shadow:var(--panel-shadow); }
  .faq button{
    width:100%; background:none; border:none; color:var(--ink); text-align:left;
    font-family:var(--font-d); font-weight:700; font-size:17px; padding:18px 20px; min-height:56px;
    display:flex; align-items:center; gap:12px; transition:background .25s;
  }
  .faq button:hover{ background:rgba(245,184,61,.06); }
  .faq button .fx{ margin-left:auto; flex:none; width:28px; height:28px; border-radius:50%; background:var(--glass2); display:grid; place-items:center; transition:transform .35s; }
  .faq.open button .fx{ transform:rotate(45deg); }
  .faq .ans{ max-height:0; overflow:hidden; transition:max-height .45s ease; }
  .faq .ans p{ padding:0 20px 19px; color:var(--muted); font-size:15.5px; }

  /* ---------- download ---------- */
  .dl-panel{
    margin-top:8px; border-radius:30px; padding:52px 34px; text-align:center; position:relative; overflow:hidden;
    background:linear-gradient(135deg, rgba(124,92,255,.35), rgba(34,195,230,.22) 48%, rgba(245,184,61,.30));
    border:1px solid var(--line); box-shadow:0 40px 100px rgba(0,0,0,.5);
  }
  .dl-panel::before{ content:""; position:absolute; width:420px; height:420px; border-radius:50%; background:radial-gradient(circle,#FF6B9D,transparent 65%); opacity:.28; filter:blur(60px); top:-200px; right:-120px; }
  .dl-panel h2{ position:relative; }
  .dl-panel .ver{ position:relative; display:inline-block; margin-top:14px; font-weight:700; color:#fff; background:rgba(10,8,26,.45); border:1px solid var(--line); padding:8px 16px; border-radius:999px; font-size:14.5px; }
  .dl-panel .cta-row{ position:relative; margin-top:28px; display:flex; justify-content:center; }
  .dl-panel .sys{ position:relative; color:rgba(255,255,255,.85); font-size:14.5px; margin-top:18px; font-weight:600; }
  .dl-count-note{ position:relative; margin-top:10px; color:rgba(255,255,255,.65); font-size:13.5px; }

  /* ---------- footer ---------- */
  footer{ margin-top:100px; background:linear-gradient(180deg,#12121A 0%,#0B0B10 100%); box-shadow:0 -18px 44px rgba(0,0,0,.35); backdrop-filter:blur(10px); }
  .foot-in{ display:flex; align-items:center; gap:18px; flex-wrap:wrap; padding:30px 0 36px; }
  .foot-in .made{ color:var(--muted); font-size:15px; }
  .wa-link{
    margin-left:auto; display:inline-flex; align-items:center; justify-content:center; gap:9px; text-decoration:none; font-weight:700; font-size:15px;
    color:#0E2A1D; background:linear-gradient(120deg,#5BE584,#25D366); padding:14px 22px; border-radius:var(--btn-radius); min-height:52px;
    box-shadow:0 10px 26px rgba(37,211,102,.35); transition:transform .25s, box-shadow .25s;
  }
  .wa-link:hover{ transform:translateY(-2px); }
  .copy{ width:100%; color:var(--faint); font-size:13.5px; padding-top:16px; display:flex; gap:10px; flex-wrap:wrap; justify-content:space-between; }

  .wa-float{
    position:fixed; right:18px; bottom:18px; z-index:70; width:56px; height:56px; border-radius:50%;
    background:linear-gradient(135deg,#5BE584,#25D366); display:grid; place-items:center;
    box-shadow:0 14px 34px rgba(37,211,102,.45); transition:transform .25s;
  }
  .wa-float:hover{ transform:scale(1.08); }

  /* ---------- responsive ---------- */
  @media (max-width:1020px){
    .nav-links{ order:3; margin-left:0; width:100%; overflow-x:auto; overflow-y:hidden; -webkit-overflow-scrolling:touch; scrollbar-width:none; }
    .nav-links::-webkit-scrollbar{ display:none; }
    .nav-cta{ margin-left:auto; }
    .hero-grid{ grid-template-columns:1fr; gap:40px; }
    .feat-grid{ grid-template-columns:1fr 1fr; }
    .steps{ grid-template-columns:1fr 1fr; }
    .step:not(:last-child)::after{ display:none; }
    .stats{ grid-template-columns:1fr 1fr; }
  }
  @media (max-width:680px){
    body{ font-size:16px; }
    section{ padding:64px 0 4px; }
    .nav-links{ order:3; margin-left:0; width:100%; overflow-x:auto; overflow-y:hidden; scrollbar-width:none; }
    .nav-links::-webkit-scrollbar{ display:none; }
    .nav-links a{ padding:9px 13px; font-size:14px; }
    .nav-cta{ margin-left:auto; padding:11px 16px; font-size:14px; min-height:46px; }
    .feat-grid,.price-grid,.demo-tiles{ grid-template-columns:1fr; }
    .steps{ grid-template-columns:1fr; }
    .stats{ grid-template-columns:1fr 1fr; gap:12px; }
    .mini-stage{ height:330px; }
    .tile-grid{ grid-template-columns:1fr 1fr; }
    .tile-grid .tile:last-child{ display:none; }
    .dl-panel{ padding:40px 20px; }
    .hero{ padding-top:40px; }
  }
  @media (prefers-reduced-motion: reduce){
    html{ scroll-behavior:auto; }
    .blob,.marquee-track,.btn-gold::after,.nav-cta::after,.btn-gen::after,.price.best .pcta::after,.splash-logo,.pill .dot,.fake-input .caret,
    .scene-tiles .tile .bar i,.dtile.working .thumb::after{ animation:none !important; }
    .rv{ opacity:1; transform:none; transition:none; }
    .scene{ transition:none; }
    .faq .ans{ transition:none; }
    .tab-indicator{ transition:none !important; }
    .btn-gold,.btn-ghost,.nav-cta,.price .pcta,.wa-link,.btn-gen,.btn-reset,.feat{ transition:none !important; }
  }
        .scale-strip{ margin-top:44px; background:var(--panel-grad); border:1px solid var(--line); border-radius:20px; padding:26px 24px; box-shadow:var(--panel-shadow); }
        .scale-strip h3{ font-family:var(--font-d); font-size:22px; }
        .scale-strip .scale-sub{ color:var(--muted); font-size:15px; margin-top:6px; max-width:46em; }
        .scale-row{ display:grid; grid-template-columns:1fr auto 1fr auto 1fr; gap:14px; align-items:stretch; margin-top:20px; }
        .scale-cell{ background:var(--panel-grad-soft); border:1px solid var(--line); border-radius:14px; padding:16px; text-align:center; }
        .scale-cell .sc-acct{ font-family:var(--font-d); font-weight:800; font-size:19px; color:#fff; }
        .scale-cell .sc-cred{ font-family:var(--font-d); font-weight:800; font-size:26px; margin-top:6px; }
        .scale-cell .sc-vid{ color:var(--muted); font-size:13.5px; margin-top:4px; font-weight:600; }
        .scale-arrow{ align-self:center; color:var(--faint); font-family:var(--font-d); font-weight:800; font-size:20px; }
        .scale-note{ color:var(--faint); font-size:13px; margin-top:14px; }
        @media (max-width:680px){ .scale-row{ grid-template-columns:1fr; } .scale-arrow{ transform:rotate(90deg); justify-self:center; } }

    .cmp-table{ width:100%; border-collapse:collapse; margin-top:26px; background:var(--panel-grad); border:1px solid var(--line); border-radius:16px; overflow:hidden; box-shadow:var(--panel-shadow); table-layout:fixed; }
    .cmp-table th,.cmp-table td{ text-align:left; padding:14px 16px; border-bottom:1px solid var(--line); font-size:15px; vertical-align:top; }
    .cmp-table th{ font-family:var(--font-d); color:#FFCE54; background:#1B1B24; }
    .cmp-table th.cmp-other{ color:var(--ink); }
    .cmp-table tr:last-child td{ border-bottom:none; }
    .cmp-table .cmp-fs{ background:rgba(245,184,61,.07); }
    .cmp-table th.cmp-fs{ background:rgba(245,184,61,.16); }
    .cmp-table td.cmp-row{ font-weight:600; color:var(--ink); }
    .cmp-cell{ display:flex; gap:8px; align-items:flex-start; }
    .cmp-cell svg{ flex:none; margin-top:3px; }
    .cmp-cell .txt{ color:var(--muted); }
    .cmp-table td.cmp-fs .txt{ color:var(--ink); }
    .mk-ok{ color:#3ED598; } .mk-no{ color:#FF8FB5; } .mk-mid{ color:var(--faint); }
    html[data-theme="light"] .cmp-table{ background:#FFFFFF; border-color:#E8E0D0; box-shadow:var(--panel-shadow); }
    html[data-theme="light"] .cmp-table th{ background:#F7F0DD; color:#8A5F0A; border-bottom-color:#E8E0D0; }
    html[data-theme="light"] .cmp-table th.cmp-other{ color:#1C1917; }
    html[data-theme="light"] .cmp-table th.cmp-fs{ background:rgba(184,134,11,.15); color:#8A5F0A; }
    html[data-theme="light"] .cmp-table td{ border-bottom-color:#E8E0D0; }
    html[data-theme="light"] .cmp-table .cmp-fs{ background:rgba(184,134,11,.06); }
    html[data-theme="light"] .mk-ok{ color:#1E9E6A; }
    html[data-theme="light"] .mk-no{ color:#C93A68; }

    /* ----- interactive mini demo: one batch, two ways ----- */
    .cmp-demo{ margin-top:44px; background:var(--panel-grad); border:1px solid var(--line); border-radius:20px; padding:26px 24px; box-shadow:var(--panel-shadow); }
    .cmp-demo h3{ font-family:var(--font-d); font-size:22px; }
    .cmp-demo h3 .grad{ font-family:var(--font-s); font-style:italic; font-weight:600; color:#FFCE54; }
    html[data-theme="light"] .cmp-demo h3 .grad{ color:#B57E0E; }
    .cmp-demo-sub{ color:var(--muted); font-size:15px; margin-top:6px; max-width:46em; }
    .cmp-controls{ display:flex; gap:18px 26px; flex-wrap:wrap; margin-top:20px; }
    .cmp-ctl-lbl{ font-size:12.5px; font-weight:700; letter-spacing:1.4px; text-transform:uppercase; color:var(--faint); margin-bottom:8px; }
    .seg{ display:inline-flex; gap:4px; background:var(--panel-grad-soft); border:1px solid var(--line); border-radius:14px; padding:4px; flex-wrap:wrap; max-width:100%; }
    .seg button{ border:none; background:transparent; color:var(--muted); font-weight:700; font-size:15px; padding:10px 18px; min-height:46px; border-radius:10px; transition:background .25s, color .25s, box-shadow .25s; }
    .seg button:hover{ color:var(--ink); }
    .seg button.on{ background:var(--gold-grad); color:#241A02; box-shadow:0 6px 16px rgba(245,184,61,.35); }
    .cmp-tracks{ margin-top:26px; display:flex; flex-direction:column; gap:22px; }
    .cmp-track-top{ display:flex; align-items:baseline; gap:10px; flex-wrap:wrap; }
    .cmp-track-name{ font-family:var(--font-d); font-weight:700; font-size:16.5px; }
    .cmp-track-day{ margin-left:auto; font-family:var(--font-d); font-weight:800; font-size:16px; white-space:nowrap; }
    .cmp-bar{ height:12px; border-radius:99px; background:color-mix(in srgb, var(--ink) 10%, transparent); overflow:hidden; margin-top:9px; }
    .cmp-bar i{ display:block; height:100%; width:0; border-radius:99px; }
    .cmp-bar.hand i{ background:linear-gradient(90deg,#9A94AC,#7A7492); }
    .cmp-bar.fs i{ background:var(--gold-grad); }
    .cmp-track-meta{ color:var(--muted); font-size:14px; margin-top:7px; }
    .cmp-run-row{ margin-top:24px; display:flex; align-items:center; gap:14px; flex-wrap:wrap; }
    .cmp-verdict{ font-weight:700; font-size:15.5px; color:var(--gold-text); }
    .cmp-note{ color:var(--faint); font-size:13px; margin-top:18px; }
    @media (max-width:680px){
      .cmp-table th,.cmp-table td{ padding:10px; font-size:13px; line-height:1.45; }
      .cmp-demo{ padding:20px 16px; }
      .seg{ width:100%; }
      .seg button{ flex:1 1 0; padding:10px 8px; }
      .cmp-run-row .btn-gen{ width:100%; }
      .cmp-verdict{ text-align:center; width:100%; }
    }
    @media (max-width:560px){
      .cmp-table th,.cmp-table td{ padding:8px; font-size:12px; }
      .cmp-cell{ gap:5px; }
      .cmp-cell svg{ width:13px; height:13px; margin-top:2px; }
      .cmp-track-day{ margin-left:0; }
    }
    @media (prefers-reduced-motion: reduce){
      .seg button{ transition:none !important; }
    }

    .shots-grid{ display:grid; grid-template-columns:1fr 1fr; gap:20px; margin-top:42px; }
    .shot-card{ background:var(--panel-grad); border:1px solid var(--line); border-radius:22px; padding:16px; box-shadow:var(--panel-shadow); transition:transform .35s cubic-bezier(.2,.7,.2,1), box-shadow .35s; }
    .shot-card:hover{ transform:translateY(-6px); box-shadow:var(--panel-shadow-lift); }
    .shot-win{ border-radius:14px; overflow:hidden; background:#0F0F16; border:1px solid #26262F; }
    .shot-bar{ display:flex; align-items:center; gap:6px; padding:9px 12px; background:#1B1B24; border-bottom:1px solid var(--line); }
    .shot-bar i{ width:9px; height:9px; border-radius:50%; display:block; }
    .shot-bar .t{ margin-left:7px; font-size:12px; font-weight:600; color:var(--faint); letter-spacing:.3px; }
    .shot-body{ padding:16px; min-height:248px; position:relative; }
    .shot-cap{ padding:14px 4px 2px; }
    .shot-cap .ct{ font-family:var(--font-d); font-weight:700; font-size:17.5px; }
    .shot-cap .cd{ color:var(--muted); font-size:14.5px; margin-top:3px; }
    /* mock 1 — portal */
    .mock-blur{ position:absolute; inset:0; padding:16px; filter:blur(4px) brightness(.6); opacity:.8; display:grid; grid-template-columns:1fr 1fr; gap:10px; align-content:start; }
    .mock-blur div{ height:52px; border-radius:10px; }
    .portal-mock{ position:relative; max-width:262px; margin:6px auto 0; background:rgba(20,20,28,.94); border:1px solid rgba(245,184,61,.35); border-radius:16px; padding:18px; box-shadow:0 22px 46px rgba(0,0,0,.55); text-align:center; }
    .portal-mock h4{ font-family:var(--font-d); font-size:16.5px; }
    .portal-mock .ps{ color:var(--muted); font-size:12.5px; margin-top:2px; }
    .g-btn{ margin-top:13px; background:#fff; color:#1F1F1F; font-weight:600; font-size:13.5px; border-radius:10px; padding:10px; display:flex; align-items:center; justify-content:center; gap:8px; min-height:40px; }
    .mock-field{ margin-top:9px; text-align:left; background:rgba(255,255,255,.06); border:1px solid var(--line); border-radius:10px; padding:9px 11px; font-size:12.5px; color:var(--muted); }
    .mock-field.gold{ border-color:rgba(245,184,61,.6); color:#FFCE54; letter-spacing:1.2px; font-weight:700; }
    .mock-activate{ margin-top:11px; background:var(--gold-grad); color:#241A02; font-weight:700; font-size:13.5px; border-radius:10px; padding:11px; min-height:42px; display:flex; align-items:center; justify-content:center; box-shadow:var(--gold-glow); }
    /* mock 2 — studio */
    .studio-mock{ display:grid; grid-template-columns:104px 1fr; gap:12px; }
    .acct{ background:var(--panel-grad-soft); border:1px solid var(--line); border-radius:10px; padding:9px 10px; margin-bottom:8px; }
    .acct .an{ font-size:12px; font-weight:700; }
    .chip{ display:inline-block; margin-top:4px; font-size:10.5px; font-weight:700; color:#FFCE54; background:rgba(245,184,61,.13); border:1px solid rgba(245,184,61,.4); padding:2px 8px; border-radius:999px; }
    .chip.low{ color:#FF8FB5; background:rgba(255,107,157,.12); border-color:rgba(255,107,157,.4); }
    .prompt-mock{ background:#0B0B10; border:1px solid var(--line); border-radius:10px; padding:10px 12px; font-size:12px; color:var(--muted); line-height:1.55; min-height:62px; }
    .gen-mock{ margin-top:10px; background:var(--gold-grad); color:#241A02; font-weight:700; font-size:13px; border-radius:10px; padding:10px; text-align:center; min-height:40px; display:flex; align-items:center; justify-content:center; box-shadow:var(--gold-glow); }
    .mini-tiles{ display:grid; grid-template-columns:1fr 1fr; gap:8px; margin-top:10px; }
    .mini-tile{ border:1px solid var(--line); border-radius:10px; padding:8px; background:var(--panel-grad-soft); }
    .mini-tile .th{ height:26px; border-radius:6px; }
    .mini-tile .sv{ display:flex; align-items:center; gap:5px; font-size:10.5px; font-weight:700; color:#3ED598; margin-top:6px; }
    /* mock 3 — downloads */
    .dl-row{ display:flex; align-items:center; gap:11px; background:var(--panel-grad-soft); border:1px solid var(--line); border-radius:12px; padding:12px; margin-bottom:10px; }
    .dl-row .fn{ font-size:13.5px; font-weight:700; }
    .dl-row .fs{ font-size:11.5px; color:var(--faint); }
    .dl-start{ margin-left:auto; flex:none; font-size:12.5px; font-weight:700; color:#241A02; background:var(--gold-grad); border-radius:9px; padding:8px 14px; min-height:36px; display:inline-flex; align-items:center; }
    .dl-saved{ margin-left:auto; flex:none; display:inline-flex; align-items:center; gap:5px; font-size:12px; font-weight:700; color:#3ED598; }
    .dl-bar{ height:5px; border-radius:99px; background:rgba(255,255,255,.12); overflow:hidden; margin-top:7px; }
    .dl-bar i{ display:block; height:100%; border-radius:99px; background:linear-gradient(90deg,#F2B544,#22C3E6); }
    /* mock 4 — agent */
    .chat-mock{ background:var(--panel-grad-soft); border:1px solid var(--line); border-radius:12px; padding:11px 13px; font-size:13px; color:var(--muted); max-width:88%; }
    .proposal-mock{ margin-top:12px; background:linear-gradient(170deg, rgba(124,92,255,.16), rgba(255,255,255,.03)); border:1px solid rgba(245,184,61,.45); border-radius:14px; padding:15px; }
    .proposal-mock .pt{ font-family:var(--font-d); font-weight:700; font-size:14.5px; }
    .proposal-mock .pc{ margin-top:7px; font-size:13.5px; color:var(--muted); }
    .proposal-mock .pc b{ color:#FFCE54; }
    .prop-btns{ display:flex; gap:9px; margin-top:13px; }
    .prop-approve{ flex:1; background:var(--gold-grad); color:#241A02; font-weight:700; font-size:13px; text-align:center; padding:10px; border-radius:10px; min-height:40px; display:flex; align-items:center; justify-content:center; }
    .prop-reject{ flex:1; background:transparent; color:var(--muted); border:1px solid var(--line); font-weight:700; font-size:13px; text-align:center; padding:10px; border-radius:10px; min-height:40px; display:flex; align-items:center; justify-content:center; }
    .guard-note{ display:flex; align-items:center; gap:6px; margin-top:11px; font-size:12px; font-weight:600; color:#3ED598; }
    @media (max-width:820px){ .shots-grid{ grid-template-columns:1fr; } .shot-body{ min-height:0; } }

  /* ===== Reference design, dark Midnight Gold conversion =====
     Warm ivory grid-paper site -> deep #0B0B10 + faint grid, rust -> app gold,
     plain-text nav, two pill button shapes only, serif-italic gold accents. */
  :root{ --font-s:"Lora", Georgia, serif; --btn-radius:14px; }
  body{
    background-color:#0B0B10;
    background-image:
      linear-gradient(rgba(255,255,255,.045) 1px, transparent 1px),
      linear-gradient(90deg, rgba(255,255,255,.045) 1px, transparent 1px);
    background-size:54px 54px;
  }
  .aurora{ display:none !important; }
  .grain{ opacity:.18; }
  #progressBar{ background:#F5B83D; box-shadow:none; height:2px; }
  ::selection{ background:#F5B83D; color:#241A02; }

  /* nav — plain text links, hairline, one gold pill */
  header.nav{ background:rgba(11,11,16,.9); border-bottom:1px solid rgba(255,255,255,.09); backdrop-filter:blur(10px); -webkit-backdrop-filter:blur(10px); }
  .nav-in{ position:relative; }
  .brand .grad{ font-family:var(--font-s); font-style:italic; font-weight:600; background:none; -webkit-background-clip:initial; background-clip:initial; color:#F5B83D; -webkit-text-fill-color:#F5B83D; }
  .nav-links{
    background:#14141C; border:1px solid rgba(255,255,255,.12); box-shadow:inset 0 1px 0 rgba(255,255,255,.04), 0 10px 26px rgba(0,0,0,.28); border-radius:14px; padding:4px; gap:2px;
    margin-left:auto; overflow:visible;
  }
  .tab-indicator{ display:none !important; }
  .nav-links a{ padding:8px 11px; border-radius:10px; min-height:40px; font-size:14px; font-weight:600; color:#C9C4B4; transition:background .22s ease, color .22s ease, transform .15s ease; }
  .nav-links a:hover{ color:#fff; background:rgba(255,255,255,.07); }
  .nav-links a:active{ transform:scale(.97); }
  .nav-links a.active{ color:#241A02; font-weight:700; background:linear-gradient(120deg,#F2B544,#DD941F); box-shadow:0 4px 14px rgba(245,184,61,.35); }
  .nav-cta{ border-radius:14px; padding:11px 20px; min-height:46px; box-shadow:0 8px 22px rgba(245,184,61,.28); }
  .menu-btn{
    display:none; margin-left:10px; width:46px; height:46px; border-radius:12px; flex:none;
    background:#14141C; border:1px solid rgba(255,255,255,.16); color:#F7F3E8;
    align-items:center; justify-content:center;
    transition:background .22s ease, border-color .22s ease, transform .15s ease;
  }
  .menu-btn:hover{ border-color:rgba(245,184,61,.6); background:#1B1B24; }
  .menu-btn:active{ transform:scale(.94); }
  .menu-btn[aria-expanded="true"]{ background:linear-gradient(120deg,#F2B544,#DD941F); border-color:transparent; color:#241A02; }
  @keyframes navDrop{ from{ opacity:0; transform:translateY(-8px) scale(.985); } to{ opacity:1; transform:none; } }
  @keyframes navLinkIn{ from{ opacity:0; transform:translateY(5px); } to{ opacity:1; transform:none; } }

  /* buttons — app style: rounded rectangles, softly curved corners (14px), never full pills */
  .btn-gold,.btn-gen,.price.best .pcta,.mock-activate,.gen-mock{ border-radius:14px !important; }
  .btn-ghost,.btn-reset,.price .pcta{ border-radius:14px; }
  .tut{ border-radius:16px; }
  .faq button .fx{ border-radius:9px; }
  .btn-ghost,.btn-reset,.price .pcta{
    background:#14141C; border:1px solid rgba(255,255,255,.18); color:#F7F3E8; box-shadow:none;
  }
  .price.best .pcta{ background:var(--gold-grad); color:#241A02; border:none; }
  .btn-ghost:hover,.btn-reset:hover,.price .pcta:hover{ border-color:rgba(245,184,61,.6); color:#FFCE54; box-shadow:none; }
  .btn-gold::after,.nav-cta::after,.btn-gen::after,.price.best .pcta::after{ display:none; }
  .wa-link{ border-radius:14px; }
  .dl-start{ border-radius:9px !important; }
  .prop-approve,.prop-reject{ border-radius:10px !important; }

  /* hero — badge, serif/sans two-line headline, stat row */
  .pill{ background:#14141C; border:1px solid rgba(255,255,255,.12); box-shadow:none; border-radius:12px; padding:5px 14px 5px 5px; gap:10px; }
  .pill-chip{ font-family:var(--font-d); font-size:11px; font-weight:800; letter-spacing:1.4px; text-transform:uppercase; color:#241A02; background:var(--gold-grad); padding:5px 10px; border-radius:8px; }
  h1{ letter-spacing:-1px; }
  h1 .h-serif{ display:block; font-family:var(--font-s); font-style:italic; font-weight:600; color:#F5B83D; letter-spacing:-.5px; }
  h1 .h-sans{ display:block; color:#F7F3E8; }
  h1 .grad{ background:none; color:#F5B83D; -webkit-text-fill-color:#F5B83D; }
  .hero-stats{ display:flex; gap:44px; flex-wrap:wrap; margin-top:34px; }
  .hs-num{ font-family:var(--font-s); font-weight:600; font-size:31px; line-height:1.1; color:#F7F3E8; }
  .hs-cap{ color:var(--faint); font-size:13.5px; margin-top:3px; }

  /* hero right — calm app window + floating stat card */
  .hero-grid > div:last-child{ position:relative; }
  .mini-shell{ background:#101016; border:1px solid rgba(255,255,255,.1); border-radius:20px; box-shadow:0 30px 60px rgba(0,0,0,.5); }
  .float-card{
    position:absolute; left:-16px; bottom:34px; z-index:3;
    background:#17171F; border:1px solid rgba(255,255,255,.12); border-radius:16px;
    padding:16px 22px; box-shadow:0 22px 44px rgba(0,0,0,.5);
  }
  .fc-lbl{ color:var(--faint); font-size:13px; font-weight:600; }
  .fc-num{ font-family:var(--font-s); font-weight:600; font-size:34px; line-height:1.15; color:#F7F3E8; }

  /* section titles — serif italic gold accent instead of rainbow gradient text */
  h2 .grad,.best-tag{ font-family:var(--font-s); font-style:italic; font-weight:600; background:none; -webkit-background-clip:initial; background-clip:initial; color:#FFCE54; -webkit-text-fill-color:#FFCE54; }
  .kicker{ letter-spacing:2px; }
  .kicker::before{ box-shadow:none; }

  /* calmer surfaces — hairlines over heavy panels */
  .feat,.step,.stat,.req-card,.legal-card,.change,.shot-card,.faq,.scale-strip,.demo-shell,.price{
    background:#111118; box-shadow:none; border-color:rgba(255,255,255,.09);
  }
  .feat:hover,.price:hover,.shot-card:hover{ box-shadow:0 18px 38px rgba(0,0,0,.4); }
  .scale-cell,.dtile,.models-table,.marquee{ background:#111118; box-shadow:none; border:1px solid rgba(255,255,255,.09); }
  .marquee{ border-radius:14px; }
  .stat .num{ font-family:var(--font-s); font-weight:600; }
  .price.best{ background:#15151D; border:1px solid rgba(245,184,61,.55); box-shadow:0 26px 54px rgba(0,0,0,.5); }
  .price.best::before{ display:none; }
  .dl-panel{ background:#13131B; border:1px solid rgba(245,184,61,.35); box-shadow:0 30px 60px rgba(0,0,0,.45); }
  .dl-panel::before{ display:none; }
  .dl-panel .ver{ background:#0B0B10; border-color:rgba(255,255,255,.14); }
  footer{ background:#0B0B10; box-shadow:none; border-top:1px solid rgba(255,255,255,.09); }

  @media (max-width:1020px){
    .menu-btn{ display:inline-flex; }
    .nav-cta{ margin-left:auto; }
    .nav-links{
      display:none; position:absolute; top:calc(100% + 10px); left:0; right:0; z-index:65;
      flex-direction:column; align-items:stretch; gap:4px;
      background:#13131B; border:1px solid rgba(255,255,255,.12); border-radius:16px; padding:8px;
      box-shadow:0 24px 48px rgba(0,0,0,.5);
    }
    .nav-links.open{ display:flex; animation:navDrop .3s cubic-bezier(.2,.8,.25,1); transform-origin:top center; }
    .nav-links.open a{ animation:navLinkIn .34s cubic-bezier(.2,.8,.25,1) both; }
    .nav-links.open a:nth-child(2){ animation-delay:.03s; } .nav-links.open a:nth-child(3){ animation-delay:.06s; }
    .nav-links.open a:nth-child(4){ animation-delay:.09s; } .nav-links.open a:nth-child(5){ animation-delay:.12s; }
    .nav-links.open a:nth-child(6){ animation-delay:.15s; } .nav-links.open a:nth-child(7){ animation-delay:.18s; }
    .nav-links.open a:nth-child(8){ animation-delay:.21s; }
    .nav-links a{ padding:12px 14px; min-height:48px; border-radius:10px; font-size:15px; }
    .nav-links a:hover{ background:rgba(255,255,255,.07); }
    .nav-links a.active{ background:linear-gradient(120deg,#F2B544,#DD941F); color:#241A02; box-shadow:0 4px 14px rgba(245,184,61,.3); }
    .float-card{ left:8px; bottom:26px; padding:13px 18px; }
    .fc-num{ font-size:28px; }
  }
  @media (max-width:680px){
    .hero-stats{ gap:26px; }
    .hs-num{ font-size:26px; }
    .float-card{ position:static; margin-top:14px; display:inline-block; }
  }
  /* ===== Theme toggle + light theme (reference look, gold accent) ===== */
  *{ transition-property:background-color, border-color, color; transition-duration:.35s; transition-timing-function:ease; }
  html{ color-scheme:dark; }
  html[data-theme="light"]{ color-scheme:light; }

  .theme-toggle{
    flex:none; display:inline-flex; align-items:center; justify-content:center;
    width:46px; height:46px; min-height:46px; padding:0; border-radius:12px;
    background:#14141C; border:1px solid rgba(255,255,255,.16); color:#FFCE54;
  }
  .theme-toggle:hover{ border-color:rgba(245,184,61,.65); }
  .theme-toggle .ic-moon{ display:none; }
  html[data-theme="light"] .theme-toggle{ background:#FFFFFF; border-color:#E0D5BC; color:#8A5F0A; }
  html[data-theme="light"] .theme-toggle .ic-sun{ display:none; }
  html[data-theme="light"] .theme-toggle .ic-moon{ display:block; }

  /* ----- light palette: warm ivory, ink text, white panels, gold accent ----- */
  html[data-theme="light"]{
    --bg:#FAF6EF; --bg2:#F4EEE1; --bg3:#FFFFFF; --panel:#FFFFFF;
    --ink:#1C1917; --muted:#55504A; --faint:#6F675C;
    --glass:#FFFFFF; --glass2:#F5EFE3; --line:#E8E0D0;
    --panel-grad:linear-gradient(180deg,#FFFFFF 0%,#FDFBF5 100%);
    --panel-grad-soft:linear-gradient(180deg,#FFFFFF 0%,#FAF6EF 100%);
    --panel-shadow:0 14px 34px rgba(122,94,32,.10), 0 2px 10px rgba(122,94,32,.05);
    --panel-shadow-lift:0 22px 48px rgba(122,94,32,.16), 0 4px 14px rgba(122,94,32,.07);
    --gold-text:#8A5F0A;
  }
  html[data-theme="light"] body{
    background-color:#FAF6EF;
    background-image:
      linear-gradient(rgba(28,25,23,.05) 1px, transparent 1px),
      linear-gradient(90deg, rgba(28,25,23,.05) 1px, transparent 1px);
  }
  html[data-theme="light"] .grain{ background-image:radial-gradient(rgba(28,25,23,.05) 1px, transparent 1px); }
  html[data-theme="light"] header.nav{ background:rgba(250,246,239,.92); border-bottom:1px solid #E8E0D0; }
  html[data-theme="light"] .nav-links a{ color:#55504A; }
  html[data-theme="light"] .nav-links a:hover{ color:#1C1917; }
  html[data-theme="light"] .nav-links{ background:#FFFFFF; border-color:#E0D5BC; }
  html[data-theme="light"] .nav-links a:hover{ background:#F7F0DD; color:#1C1917; }
  html[data-theme="light"] .nav-links a.active{ color:#241A02; background:linear-gradient(120deg,#F2B544,#DD941F); box-shadow:0 4px 14px rgba(184,134,11,.3); }
  html[data-theme="light"] .menu-btn{ background:#FFFFFF; border-color:#E0D5BC; color:#1C1917; }
  html[data-theme="light"] .brand .grad{ color:#B57E0E; -webkit-text-fill-color:#B57E0E; }

  html[data-theme="light"] .pill{ background:#FFFFFF; border-color:#E8E0D0; }
  html[data-theme="light"] h1 .h-sans{ color:#1C1917; }
  html[data-theme="light"] h1 .h-serif, html[data-theme="light"] h1 .grad{ color:#B57E0E; -webkit-text-fill-color:#B57E0E; }
  html[data-theme="light"] h2 .grad, html[data-theme="light"] .best-tag{ color:#B57E0E; -webkit-text-fill-color:#B57E0E; }
  html[data-theme="light"] .kicker{ color:#8A5F0A !important; }
  html[data-theme="light"] .hs-num{ color:#1C1917; }

  /* white surfaces with warm shadows + hairlines */
  html[data-theme="light"] .feat, html[data-theme="light"] .step, html[data-theme="light"] .stat,
  html[data-theme="light"] .req-card, html[data-theme="light"] .legal-card, html[data-theme="light"] .change,
  html[data-theme="light"] .shot-card, html[data-theme="light"] .faq, html[data-theme="light"] .scale-strip,
  html[data-theme="light"] .price{
    background:#FFFFFF; border-color:#E8E0D0; box-shadow:var(--panel-shadow);
  }
  html[data-theme="light"] .feat:hover, html[data-theme="light"] .price:hover, html[data-theme="light"] .shot-card:hover{ box-shadow:var(--panel-shadow-lift); }
  html[data-theme="light"] .scale-cell, html[data-theme="light"] .marquee{ background:#FFFFFF; border-color:#E8E0D0; box-shadow:var(--panel-shadow); }
  html[data-theme="light"] .scale-cell .sc-acct{ color:#1C1917; }
  html[data-theme="light"] .scale-cell .sc-cred{ color:#8A5F0A !important; }
  html[data-theme="light"] .change .ver-badge{ color:#8A5F0A; }
  html[data-theme="light"] .st-wait{ color:#8A5F0A; }
  html[data-theme="light"] .models-table{ background:#FFFFFF; border-color:#E8E0D0; box-shadow:var(--panel-shadow); }
  html[data-theme="light"] .models-table th{ background:#F7F0DD; color:#8A5F0A; border-bottom-color:#E8E0D0; }
  html[data-theme="light"] .models-table td{ border-bottom-color:#E8E0D0; }
  html[data-theme="light"] .activity-table th, html[data-theme="light"] .activity-table td{ border-bottom-color:#E8E0D0; }
  html[data-theme="light"] .faq button:hover{ background:rgba(184,134,11,.07); }

  /* outline pills: white bg + dark border + dark text */
  html[data-theme="light"] .btn-ghost, html[data-theme="light"] .price .pcta{
    background:#FFFFFF; border:1px solid #1C1917; color:#1C1917; box-shadow:none;
  }
  html[data-theme="light"] .btn-ghost:hover, html[data-theme="light"] .price .pcta:hover{ border-color:#B57E0E; color:#8A5F0A; box-shadow:none; }
  html[data-theme="light"] .price.best{ background:#FFFDF6; border-color:rgba(184,134,11,.55); box-shadow:var(--panel-shadow-lift); }
  html[data-theme="light"] .price.best .pcta{ background:var(--gold-grad); color:#241A02; border:none; }
  html[data-theme="light"] #pricing .wrap > p[style]{ color:#8A5F0A !important; }

  /* floating stat card: white with ink numbers */
  html[data-theme="light"] .float-card{ background:#FFFFFF; border-color:#E8E0D0; box-shadow:0 22px 44px rgba(122,94,32,.18); }
  html[data-theme="light"] .fc-num{ color:#1C1917; }

  /* download panel + footer */
  html[data-theme="light"] .dl-panel{ background:linear-gradient(180deg,#FFFDF6 0%,#FBF2DC 100%); border-color:rgba(184,134,11,.45); box-shadow:0 30px 60px rgba(122,94,32,.18); }
  html[data-theme="light"] .dl-panel .ver{ background:#FFFFFF; border-color:#E0D5BC; color:#1C1917; }
  html[data-theme="light"] .dl-panel .sys{ color:#55504A; }
  html[data-theme="light"] footer{ background:#F7F1E5; border-top:1px solid #E8E0D0; }

  /* app-window frames stay DARK in both themes — they picture the app itself */
  html[data-theme="light"] .mini-shell, html[data-theme="light"] .demo-shell, html[data-theme="light"] .shot-win{
    --ink:#F7F3E8; --muted:#C9C4B4; --faint:#97917F;
    --glass:#14141C; --glass2:#1B1B24; --line:#26262F;
    --panel-grad:linear-gradient(180deg,#1C1C26 0%,#14141C 100%);
    --panel-grad-soft:linear-gradient(180deg,#191922 0%,#12121A 100%);
    --panel-shadow:0 14px 34px rgba(0,0,0,.38), 0 2px 10px rgba(0,0,0,.28);
    --panel-shadow-lift:0 22px 48px rgba(0,0,0,.45), 0 4px 14px rgba(0,0,0,.3);
    --gold-text:#FFCE54;
    color:#F7F3E8;
  }
  html[data-theme="light"] .mini-shell{ box-shadow:0 30px 60px rgba(122,94,32,.25); }

  @media (max-width:1020px){
    html[data-theme="light"] .nav-links{ background:#FFFFFF; border-color:#E8E0D0; box-shadow:0 24px 48px rgba(122,94,32,.18); }
    html[data-theme="light"] .nav-links a.active{ background:linear-gradient(120deg,#F2B544,#DD941F); color:#241A02; }
  }
  /* ===== Mobile pass — phones & small tablets only. Desktop (>1020px) is untouched. ===== */

  /* tablet: floating stat card stacks under the hero window instead of overlapping it */
  @media (max-width:900px){
    .float-card{ position:static; margin-top:14px; display:inline-block; }
  }

  @media (max-width:680px){
    .wrap{ padding:0 16px; }
    section{ scroll-margin-top:136px; }

    /* full-width controls must include their padding, or they spill past the screen edge */
    .nav-cta, .hero-cta .btn-gold, .hero-cta .btn-ghost, .btn-gen, .btn-reset,
    .dl-panel .cta-row .btn-gold, .foot-in .wa-link, .demo-prompts, .cmp-run-row .btn-gen,
    .faq button{
      box-sizing:border-box;
    }

    /* tutorials: one calm column instead of two squeezed ones */
    .tut-list{ grid-template-columns:1fr; }
    .tut{ min-height:64px; padding:14px 16px; }

    /* header: one tidy row (logo · theme · menu), gold Download as a full-width bar under it */
    .nav-in{ gap:10px; padding:10px 0 12px; }
    .brand{ order:0; font-size:19px; }
    .theme-toggle{ order:1; margin-left:auto; width:44px; height:44px; min-height:44px; }
    .menu-btn{ order:2; margin-left:0; width:44px; height:44px; }
    .nav-cta{
      order:3; flex:1 1 100%; width:100%; margin-left:0;
      justify-content:center; text-align:center;
      padding:12px 18px; min-height:48px; font-size:15px;
    }

    /* hero: fluid type, full-width stacked buttons */
    .hero{ padding:36px 0 24px; }
    h1{ font-size:clamp(35px, 10.5vw, 46px); }
    .hero-sub{ font-size:16.5px; margin-top:14px; }
    .pill{ font-size:12.5px; max-width:100%; flex-wrap:wrap; row-gap:6px; }
    .hero-cta{ flex-direction:column; align-items:stretch; gap:12px; margin-top:24px; }
    .hero-cta .btn-gold, .hero-cta .btn-ghost{ width:100%; text-align:center; }
    .hero-cta .btn-gold{ font-size:15.5px; padding:14px 18px; line-height:1.35; }
    .hero-stats{ gap:20px 26px; margin-top:28px; }
    .marquee{ margin-top:40px; }
    .marquee span{ font-size:14px; padding:0 16px; }

    /* hero demo window: tighter chrome, scenes keep room to breathe */
    .mini-shell{ padding:10px; border-radius:20px; }
    .mini-bar .t{ font-size:12px; }
    .scene{ padding:16px; }
    .portal-card{ padding:16px; margin-top:8px; }
    .saved-row{ margin-top:12px; }

    /* stats: keep the 2x2 wrap, tighten the cards */
    .stats{ gap:12px; margin-top:32px; }
    .stat{ padding:18px 16px; }
    .stat .lbl{ font-size:13.5px; }

    /* studio demo: full-width tappable actions, no iOS focus zoom */
    .demo-shell{ padding:16px; border-radius:20px; }
    .demo-top .ttl{ font-size:17px; }
    .demo-prompts{ font-size:16px; }
    .demo-actions{ flex-direction:column; align-items:stretch; gap:10px; }
    .btn-gen, .btn-reset{ width:100%; min-height:52px; }
    .demo-status{ text-align:center; }

    /* screenshots: calmer padding inside the app windows */
    .shot-card{ padding:12px; }
    .shot-body{ padding:12px; }

    /* download panel + footer stack cleanly */
    .dl-panel .cta-row .btn-gold{ width:100%; }
    .foot-in{ gap:14px; }
    .foot-in .wa-link{ margin-left:0; width:100%; }
    .copy{ flex-direction:column; gap:4px; }

    /* floating WhatsApp: smaller, lifted off the edge, respects the home-bar area */
    .wa-float{
      width:52px; height:52px; right:14px;
      bottom:calc(14px + env(safe-area-inset-bottom, 0px));
    }
  }

  @media (max-width:560px){
    /* the one wide stat word ("Unlimited" — the only .num with an inline size) must never clip its card */
    .stats .num[style]{ font-size:22px !important; }

    /* models & credits: smaller type + tight cells so the table fits, no sideways scroll */
    .models-table{ margin-top:20px; }
    .models-table th, .models-table td{ padding:10px; font-size:13.5px; line-height:1.45; }

    /* studio screenshot mock: accounts become a 3-up row above the prompt box */
    .studio-mock{ grid-template-columns:1fr; }
    .studio-mock > div:first-child{ display:grid; grid-template-columns:repeat(3,1fr); gap:8px; }
    .studio-mock .acct{ margin-bottom:0; padding:8px; }
    .studio-mock .acct .an{ font-size:11.5px; }

    .price .amt{ font-size:38px; }
    .change{ padding:18px; }
    .faq button{ font-size:16px; padding:16px; }
    .dl-panel h2{ font-size:27px; }
  }
  /* ===== App-style finish: softly curved buttons everywhere, no full-pill shapes ===== */
  .btn-gold,.btn-ghost,.btn-gen,.btn-reset,.nav-cta,.wa-link,.price .pcta{ border-radius:14px; }
  .btn-gold:active,.btn-gen:active,.nav-cta:active,.btn-ghost:active,.btn-reset:active{ transform:scale(.98); }
  .credits-chip{ border-radius:10px; }
  .live-tag{ border-radius:8px; }
  .dl-panel .ver{ border-radius:10px; }
  .best-tag{ border-radius:8px; }
  .chip{ border-radius:6px; }
  #pricing .wrap > p[style]{ border-radius:10px !important; }
  .step .n{ border-radius:12px; }
  .tut .play{ border-radius:14px; }
  .wa-float{ border-radius:16px; }
  .theme-toggle:active{ transform:scale(.94); }
  .theme-toggle{ transition:background .22s ease, border-color .22s ease, transform .15s ease; }
  @media (prefers-reduced-motion: reduce){
    .nav-links.open,.nav-links.open a{ animation:none !important; }
    .btn-gold:active,.btn-gen:active,.nav-cta:active,.btn-ghost:active,.btn-reset:active,.theme-toggle:active,.menu-btn:active,.nav-links a:active{ transform:none !important; }
  }
  /* ===== Mobile & tablet menu — the opened panel is a floating card, not a full-width slab.
     Everything here is scoped to <=1020px (plus the menu button's open/close icon swap;
     that button is hidden on desktop). Desktop rendering is untouched. ===== */
  .menu-btn .ic-close{ display:none; }
  .menu-btn[aria-expanded="true"] .ic-burger{ display:none; }
  .menu-btn[aria-expanded="true"] .ic-close{ display:block; }

  @keyframes menuDrop{ from{ opacity:0; transform:translateY(-10px) scale(.97); } to{ opacity:1; transform:none; } }

  @media (max-width:1020px){
    .nav-links{
      top:calc(100% + 12px);
      padding:10px; gap:3px; border-radius:20px;
      background:linear-gradient(180deg,#1A1A24 0%,#12121A 100%);
      border:1px solid rgba(255,255,255,.13);
      box-shadow:0 30px 60px rgba(0,0,0,.55), 0 8px 22px rgba(0,0,0,.4), inset 0 1px 0 rgba(255,255,255,.06);
      max-height:calc(100vh - 158px); max-height:calc(100dvh - 158px);
      overflow-y:auto; overflow-x:hidden; overscroll-behavior:contain; scrollbar-width:thin;
    }
    .nav-links.open{ animation:menuDrop .32s cubic-bezier(.2,.8,.25,1); transform-origin:top right; }
    .nav-links a{
      display:flex; align-items:center;
      min-height:52px; padding:13px 16px; border-radius:13px;
      font-size:15.5px; font-weight:600;
    }
    /* quiet chevron on every row — gold and stronger on the current page */
    .nav-links a::after{
      content:""; margin-left:auto; flex:none; width:8px; height:8px;
      border-top:2px solid currentColor; border-right:2px solid currentColor;
      transform:rotate(45deg); opacity:.3;
    }
    .nav-links a.active::after{ opacity:.75; }
    /* hairline between rows; never above the gold active row or right below it */
    .nav-links a + a{ box-shadow:inset 0 1px 0 rgba(255,255,255,.05); }
    .nav-links a.active{ box-shadow:0 6px 18px rgba(245,184,61,.35); }
    .nav-links a.active + a{ box-shadow:none; }

    html[data-theme="light"] .nav-links{
      background:linear-gradient(180deg,#FFFFFF 0%,#FBF6EA 100%);
      border-color:#E8E0D0;
      box-shadow:0 30px 60px rgba(122,94,32,.22), 0 8px 22px rgba(122,94,32,.12), inset 0 1px 0 #FFFFFF;
    }
    html[data-theme="light"] .nav-links a + a{ box-shadow:inset 0 1px 0 rgba(28,25,23,.06); }
    html[data-theme="light"] .nav-links a.active{ box-shadow:0 6px 18px rgba(184,134,11,.3); }
    html[data-theme="light"] .nav-links a.active + a{ box-shadow:none; }
  }

  /* tablet: the panel hugs the right edge under the menu button instead of stretching full width */
  @media (min-width:681px) and (max-width:1020px){
    .nav-links{ left:auto; width:min(360px, 100%); }
  }

  @media (prefers-reduced-motion: reduce){
    .nav-links.open{ animation:none !important; }
  }
  /* ===== Button samples — six medium-build styles to pick from.
     Every primary/secondary/menu row below is medium: 40–46px tall, never the old 52px chunk.
     The picked style is mirrored onto the site's real buttons via html[data-btnstyle]. ===== */
  html{ overflow-x:clip; }

  /* the picker must be tappable the moment it is reached — no scroll-reveal hiding */
  #buttons .rv{ opacity:1 !important; transform:none !important; }

  .bs-picked{
    margin-top:16px; display:inline-block; padding:10px 16px; border-radius:12px;
    background:var(--glass); border:1px dashed rgba(245,184,61,.55); color:var(--muted);
    font-size:14.5px; font-weight:600;
  }
  .bs-picked b{ color:var(--gold-text); }
  .bs-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:16px; margin-top:28px; }
  .bs-card{
    background:var(--panel-grad); border:1px solid var(--line); border-radius:18px;
    padding:20px; box-shadow:var(--panel-shadow); display:flex; flex-direction:column; gap:14px;
    transition:border-color .25s, box-shadow .25s;
  }
  .bs-card.picked{ border-color:#F5B83D; box-shadow:0 0 0 1px #F5B83D, var(--panel-shadow-lift); }
  .bs-head{ display:flex; gap:12px; align-items:flex-start; }
  .bs-num{
    flex:none; width:34px; height:34px; border-radius:10px; display:grid; place-items:center;
    background:var(--gold-grad); color:#241A02; font-family:var(--font-d); font-weight:800; font-size:17px;
  }
  .bs-head h3{ font-family:var(--font-d); font-size:18.5px; line-height:1.25; }
  .bs-where{ color:var(--faint); font-size:13.5px; margin-top:2px; line-height:1.45; }
  .bs-stage{
    background:var(--glass2); border:1px solid var(--line); border-radius:14px; padding:16px;
    display:flex; flex-wrap:wrap; gap:10px; align-items:center;
  }
  .bs-menu{ flex:1 1 100%; display:flex; flex-direction:column; gap:4px; margin-top:4px; }
  .bs-row{ display:flex; align-items:center; color:var(--muted); font-weight:600; }
  .bs-row.on{ background:var(--gold-grad); color:#241A02; font-weight:700; }
  .bs-spec{ color:var(--faint); font-size:13px; }
  .bs-pick{
    margin-top:auto; align-self:flex-start; border:1px solid rgba(245,184,61,.6); background:transparent;
    color:var(--gold-text); font-weight:700; font-size:14px; padding:10px 18px; min-height:42px; border-radius:10px;
    transition:background .2s, color .2s, transform .15s;
  }
  .bs-pick:hover{ background:rgba(245,184,61,.12); }
  .bs-pick:active{ transform:scale(.97); }
  .bs-card.picked .bs-pick{ background:var(--gold-grad); color:#241A02; border-color:transparent; }

  /* shared sample-button base */
  .bs-p,.bs-s{ display:inline-flex; align-items:center; justify-content:center; gap:8px; text-decoration:none; white-space:nowrap; }
  .bs-p{ background:var(--gold-grad); color:#241A02; }
  .bs-s{ background:#14141C; border:1px solid rgba(255,255,255,.18); color:#F7F3E8; }
  html[data-theme="light"] .bs-s{ background:#FFFFFF; border-color:#1C1917; color:#1C1917; }
  html[data-theme="light"] .bs6-p{ background:rgba(184,134,11,.1); }

  /* 1 · Modern Standard — 44px, 10px corners */
  .bs1-p{ height:44px; padding:0 22px; border-radius:10px; font-size:15px; font-weight:600; box-shadow:0 6px 16px rgba(245,184,61,.3); }
  .bs1-s{ height:44px; padding:0 20px; border-radius:10px; font-size:15px; font-weight:600; }
  .bs1-row{ height:44px; padding:0 14px; border-radius:10px; font-size:14.5px; }
  /* 2 · Soft Rounded — 46px, 14px corners */
  .bs2-p{ height:46px; padding:0 24px; border-radius:14px; font-size:15px; font-weight:700; box-shadow:0 8px 20px rgba(245,184,61,.32); }
  .bs2-s{ height:46px; padding:0 22px; border-radius:14px; font-size:15px; font-weight:600; }
  .bs2-row{ height:46px; padding:0 15px; border-radius:13px; font-size:15px; }
  /* 3 · Full Pill — 44px, round ends */
  .bs3-p{ height:44px; padding:0 26px; border-radius:999px; font-size:15px; font-weight:600; box-shadow:0 6px 16px rgba(245,184,61,.3); }
  .bs3-s{ height:44px; padding:0 24px; border-radius:999px; font-size:15px; font-weight:600; }
  .bs3-row{ height:44px; padding:0 16px; border-radius:999px; font-size:14.5px; }
  /* 4 · Compact Sharp — 40px, 6px corners */
  .bs4-p{ height:40px; padding:0 18px; border-radius:6px; font-size:14px; font-weight:600; box-shadow:0 4px 12px rgba(245,184,61,.28); }
  .bs4-s{ height:40px; padding:0 16px; border-radius:6px; font-size:14px; font-weight:600; }
  .bs4-row{ height:40px; padding:0 12px; border-radius:6px; font-size:14px; }
  /* 5 · Flat Minimal — 44px, 10px corners, solid colour, no shadow */
  .bs5-p{ height:44px; padding:0 22px; border-radius:10px; font-size:15px; font-weight:600; background:#F0AC2C; box-shadow:none; }
  .bs5-s{ height:44px; padding:0 20px; border-radius:10px; font-size:15px; font-weight:600; background:transparent; }
  .bs5-row{ height:44px; padding:0 14px; border-radius:10px; font-size:14.5px; background:transparent; }
  .bs5-row.on{ background:#F0AC2C; box-shadow:none; }
  /* 6 · Outline Mix — 44px, 12px corners, gold outline + tint */
  .bs6-p{ height:44px; padding:0 22px; border-radius:12px; font-size:15px; font-weight:700; background:rgba(245,184,61,.14); border:1.5px solid #F5B83D; color:var(--gold-text); box-shadow:none; }
  .bs6-s{ height:44px; padding:0 20px; border-radius:12px; font-size:15px; font-weight:600; background:transparent; }
  .bs6-row{ height:44px; padding:0 14px; border-radius:12px; font-size:14.5px; }

  @media (max-width:1020px){ .bs-grid{ grid-template-columns:repeat(2,1fr); } }
  @media (max-width:680px){
    .bs-grid{ grid-template-columns:1fr; }
    .bs-card{ padding:16px; }
    .bs-p,.bs-s{ flex:1 1 auto; }
    .bs-pick{ width:100%; text-align:center; }
  }

  /* ===== the picked style, applied to the site's real buttons ===== */
  html[data-btnstyle="1"]{ --btn-radius:10px; }
  html[data-btnstyle="1"] .btn-gold, html[data-btnstyle="1"] .btn-ghost, html[data-btnstyle="1"] .btn-gen, html[data-btnstyle="1"] .btn-reset{ min-height:44px; padding-top:0; padding-bottom:0; font-size:15px; font-weight:600; box-shadow:0 6px 16px rgba(245,184,61,.3); }
  html[data-btnstyle="1"] .nav-cta{ min-height:44px; padding-top:0; padding-bottom:0; font-size:15px; font-weight:600; }
  @media (max-width:1020px){ html[data-btnstyle="1"] .nav-links a{ min-height:44px; border-radius:10px; font-size:14.5px; } }

  html[data-btnstyle="2"]{ --btn-radius:14px; }
  html[data-btnstyle="2"] .btn-gold, html[data-btnstyle="2"] .btn-ghost, html[data-btnstyle="2"] .btn-gen, html[data-btnstyle="2"] .btn-reset{ min-height:46px; padding-top:0; padding-bottom:0; font-size:15px; }
  html[data-btnstyle="2"] .nav-cta{ min-height:46px; padding-top:0; padding-bottom:0; font-size:15px; }
  @media (max-width:1020px){ html[data-btnstyle="2"] .nav-links a{ min-height:46px; border-radius:13px; font-size:15px; } }

  html[data-btnstyle="3"]{ --btn-radius:999px; }
  html[data-btnstyle="3"] .btn-gold, html[data-btnstyle="3"] .btn-ghost, html[data-btnstyle="3"] .btn-gen, html[data-btnstyle="3"] .btn-reset{ min-height:44px; padding-top:0; padding-bottom:0; font-size:15px; font-weight:600; box-shadow:0 6px 16px rgba(245,184,61,.3); border-radius:999px; }
  html[data-btnstyle="3"] .nav-cta{ min-height:44px; padding-top:0; padding-bottom:0; font-size:15px; font-weight:600; border-radius:999px; }
  html[data-btnstyle="3"] .price .pcta{ border-radius:999px; }
  @media (max-width:1020px){ html[data-btnstyle="3"] .nav-links a{ min-height:44px; border-radius:999px; font-size:14.5px; } }

  html[data-btnstyle="4"]{ --btn-radius:6px; }
  html[data-btnstyle="4"] .btn-gold, html[data-btnstyle="4"] .btn-ghost, html[data-btnstyle="4"] .btn-gen, html[data-btnstyle="4"] .btn-reset{ min-height:40px; padding-top:0; padding-bottom:0; font-size:14px; font-weight:600; box-shadow:0 4px 12px rgba(245,184,61,.28); border-radius:6px; }
  html[data-btnstyle="4"] .nav-cta{ min-height:40px; padding-top:0; padding-bottom:0; font-size:14px; font-weight:600; border-radius:6px; }
  html[data-btnstyle="4"] .price .pcta{ border-radius:6px; }
  @media (max-width:1020px){ html[data-btnstyle="4"] .nav-links a{ min-height:40px; border-radius:6px; font-size:14px; } }

  html[data-btnstyle="5"]{ --btn-radius:10px; }
  html[data-btnstyle="5"] .btn-gold, html[data-btnstyle="5"] .btn-gen{ min-height:44px; padding-top:0; padding-bottom:0; font-size:15px; font-weight:600; background:#F0AC2C; box-shadow:none; border-radius:10px; }
  html[data-btnstyle="5"] .btn-ghost, html[data-btnstyle="5"] .btn-reset{ min-height:44px; padding-top:0; padding-bottom:0; font-size:15px; font-weight:600; background:transparent; box-shadow:none; border-radius:10px; }
  html[data-btnstyle="5"] .nav-cta{ min-height:44px; padding-top:0; padding-bottom:0; font-size:15px; font-weight:600; background:#F0AC2C; box-shadow:none; border-radius:10px; }
  html[data-btnstyle="5"] .nav-links a.active{ background:#F0AC2C; box-shadow:none; }
  html[data-btnstyle="5"] .price .pcta{ border-radius:10px; }
  html[data-btnstyle="5"] .price.best .pcta{ background:#F0AC2C; box-shadow:none; }
  @media (max-width:1020px){ html[data-btnstyle="5"] .nav-links a{ min-height:44px; border-radius:10px; font-size:14.5px; } html[data-btnstyle="5"] .nav-links a.active{ box-shadow:none; } }

  html[data-btnstyle="6"]{ --btn-radius:12px; }
  html[data-btnstyle="6"] .btn-gold, html[data-btnstyle="6"] .btn-gen{ min-height:44px; padding-top:0; padding-bottom:0; font-size:15px; font-weight:700; background:rgba(245,184,61,.14); border:1.5px solid #F5B83D; color:var(--gold-text); box-shadow:none; border-radius:12px; }
  html[data-btnstyle="6"] .btn-ghost, html[data-btnstyle="6"] .btn-reset{ min-height:44px; padding-top:0; padding-bottom:0; font-size:15px; font-weight:600; background:transparent; border-radius:12px; }
  html[data-btnstyle="6"] .nav-cta{ min-height:44px; padding-top:0; padding-bottom:0; font-size:15px; font-weight:700; background:rgba(245,184,61,.14); border:1.5px solid #F5B83D; color:var(--gold-text); box-shadow:none; border-radius:12px; }
  html[data-btnstyle="6"] .price .pcta{ border-radius:12px; }
  html[data-btnstyle="6"] .price.best .pcta{ background:rgba(245,184,61,.14); border:1.5px solid #F5B83D; color:var(--gold-text); }
  @media (max-width:1020px){ html[data-btnstyle="6"] .nav-links a{ min-height:44px; border-radius:12px; font-size:14.5px; } }
  /* ===== The picked button standard, desktop and mobile alike —
     Sample 2: 48px height, 0 26px side padding, 8px corners, 15px bold text.
     Desktop: buttons only — the tab/nav menu stays exactly as it is. ===== */
  .btn-gold,.btn-ghost,.btn-gen,.btn-reset,.price .pcta,.wa-link{
    min-height:48px; padding:0 26px; font-size:15px; font-weight:700; border-radius:8px; max-width:100%;
  }
  .nav-cta{ min-height:48px; padding:0 20px; font-size:15px; border-radius:8px; }
  /* hero pair: same standard — the mobile hero rule's taller padding must not win */
  .hero-cta .btn-gold,.hero-cta .btn-ghost{ padding-top:0; padding-bottom:0; font-size:15px; }

  /* ===== Mobile only (<=1020px): Menu B — every menu item its own separate
     button, sitting on ONE solid opaque panel so the page behind the open
     menu never shows through the gaps between the buttons.
     Open/close behaviour unchanged, desktop menu untouched. ===== */
  @media (max-width:1020px){
    .nav-links{
      background:linear-gradient(180deg,#1A1A24 0%,#12121A 100%);
      border:1px solid rgba(255,255,255,.13); border-radius:18px;
      box-shadow:0 30px 60px rgba(0,0,0,.6), 0 8px 22px rgba(0,0,0,.45);
      padding:10px; gap:8px;
    }
    .nav-links a{
      display:flex; align-items:center; justify-content:space-between;
      min-height:48px; padding:0 14px; border-radius:11px;
      background:#26262F; border:1px solid #3A3A45; color:#fff; font-size:14px; font-weight:600;
    }
    .nav-links a::after{ content:"\203A"; font-size:19px; font-weight:400; line-height:1; opacity:.55; width:auto; height:auto; border:none; transform:none; margin-left:0; }
    .nav-links a:not(.active){ box-shadow:none; }
    .nav-links a:hover{ background:#30303B; color:#fff; }
    .nav-links a.active{ background:linear-gradient(120deg,#F2B544,#DD941F); border-color:transparent; color:#241A02; box-shadow:0 4px 14px rgba(245,184,61,.3); }
    .nav-links a.active::after{ opacity:.85; }
    html[data-theme="light"] .nav-links{
      background:linear-gradient(180deg,#FFFFFF 0%,#FBF6EA 100%);
      border:1px solid #E8E0D0;
      box-shadow:0 30px 60px rgba(122,94,32,.25), 0 8px 22px rgba(122,94,32,.14);
    }
    html[data-theme="light"] .nav-links a{ background:#FFFFFF; border-color:#D9CCAB; color:#1C1917; }
    html[data-theme="light"] .nav-links a:hover{ background:#FBF6E9; color:#1C1917; }
    html[data-theme="light"] .nav-links a:not(.active){ box-shadow:none; }
    html[data-theme="light"] .nav-links a.active{ background:linear-gradient(120deg,#F2B544,#DD941F); border-color:transparent; color:#241A02; }
  }

  /* ===== Desktop only (>1020px): the tab menu goes back to how it was
     before — plain text links, no button look at all. No track/panel
     behind the links, no gold pill on the current page; the active
     page is just gold text. The button-style menu stays ONLY in the
     mobile/tablet dropdown above. Everything else is untouched. ===== */
  @media (min-width:1021px){
    .nav-links{ background:transparent; border:none; box-shadow:none; padding:0; border-radius:0; gap:4px; }
    .nav-links a{ background:transparent; border:none; box-shadow:none; border-radius:0; min-height:0; padding:8px 10px; }
    .nav-links a:hover{ background:transparent; color:#fff; }
    .nav-links a:active{ transform:none; }
    .nav-links a.active{ background:transparent; box-shadow:none; color:#FFCE54; font-weight:700; }
    html[data-theme="light"] .nav-links{ background:transparent; border:none; box-shadow:none; }
    html[data-theme="light"] .nav-links a{ background:transparent; }
    html[data-theme="light"] .nav-links a:hover{ background:transparent; color:#1C1917; }
    html[data-theme="light"] .nav-links a.active{ background:transparent; box-shadow:none; color:#8A5F0A; }
  }

.foot-links{display:flex;flex-wrap:wrap;gap:8px 18px;justify-content:center;padding:16px 0 2px}
.foot-links a{color:var(--muted);text-decoration:none;font-size:13.5px}
.foot-links a:hover{color:var(--gold-text)}

body.script:
//
(function(){
  var btn = document.getElementById("menuBtn");
  var nav = document.getElementById("tabTrack");
  if (!btn || !nav) return;
  function close(){
    nav.classList.remove("open");
    btn.setAttribute("aria-expanded", "false");
    btn.setAttribute("aria-label", "Open menu");
  }
  btn.addEventListener("click", function(){
    var open = nav.classList.toggle("open");
    btn.setAttribute("aria-expanded", open ? "true" : "false");
    btn.setAttribute("aria-label", open ? "Close menu" : "Open menu");
  });
  nav.querySelectorAll("a").forEach(function(a){
    a.addEventListener("click", close);
  });
  document.addEventListener("click", function(e){
    if (nav.classList.contains("open") && !nav.contains(e.target) && !btn.contains(e.target)) close();
  });
  document.addEventListener("keydown", function(e){
    if (e.key === "Escape" && nav.classList.contains("open")){ close(); btn.focus(); }
  });
})();
//

//
(function(){
  var btn = document.getElementById("themeToggle");
  if (!btn) return;
  function sync(){
    var light = document.documentElement.getAttribute("data-theme") === "light";
    btn.setAttribute("aria-pressed", light ? "true" : "false");
    btn.setAttribute("aria-label", light ? "Switch to dark mode" : "Switch to light mode");
  }
  btn.addEventListener("click", function(){
    var next = document.documentElement.getAttribute("data-theme") === "light" ? "dark" : "light";
    document.documentElement.setAttribute("data-theme", next);
    try { localStorage.setItem("fs-theme", next); } catch (e) {}
    sync();
  });
  sync();
})();
//

//
(function(){
  "use strict";
  var reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  document.getElementById("year").textContent = new Date().getFullYear();

  /* duplicate marquee content for a seamless loop */
  var track = document.getElementById("marqueeTrack");
  if (track){ track.innerHTML += track.innerHTML; }

  /* ---------- scroll reveals + counters ---------- */
  function animateCount(el){
    var target = parseFloat(el.getAttribute("data-count"));
    var prefix = el.getAttribute("data-prefix") || "";
    var suffix = el.getAttribute("data-suffix") || "";
    if (reduced){ el.textContent = prefix + target.toLocaleString("en-US") + suffix; return; }
    var start = null, dur = 1400;
    function step(ts){
      if (!start) start = ts;
      var p = Math.min((ts - start) / dur, 1);
      var eased = 1 - Math.pow(1 - p, 3);
      el.textContent = prefix + Math.round(target * eased).toLocaleString("en-US") + suffix;
      if (p < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting){
        e.target.classList.add("in");
        e.target.querySelectorAll("[data-count]").forEach(function(c){
          if (!c.dataset.done){ c.dataset.done = "1"; animateCount(c); }
        });
        io.unobserve(e.target);
      }
    });
  }, { threshold: 0.14 });
  document.querySelectorAll(".rv").forEach(function(el){ io.observe(el); });

  /* ---------- gentle parallax on aurora blobs ---------- */
  if (!reduced){
    var blobs = document.querySelectorAll("[data-parallax]");
    var ticking = false;
    window.addEventListener("scroll", function(){
      if (ticking) return; ticking = true;
      requestAnimationFrame(function(){
        var y = window.scrollY;
        blobs.forEach(function(b){
          var f = parseFloat(b.getAttribute("data-parallax"));
          b.style.translate = "0 " + (y * f / 100) + "px";
        });
        ticking = false;
      });
    }, { passive: true });
  }

  /* ---------- hero mini demo loop ---------- */
  var scenes = document.querySelectorAll("#miniStage .scene");
  var dots = document.querySelectorAll("#miniDots i");
  var splashStatus = document.getElementById("splashStatus");
  var keyType = document.getElementById("keyType");
  var splashLines = ["Engine starting…", "Accounts getting ready…", "Almost there…"];
  var sceneIdx = 0, sceneTimer = null, splashTimer = null, keyTimer = null;

  function showScene(i){
    sceneIdx = i;
    scenes.forEach(function(s, j){ s.classList.toggle("on", j === i); });
    dots.forEach(function(d, j){ d.classList.toggle("on", j === i); });
    clearInterval(splashTimer); clearInterval(keyTimer);
    if (i === 0 && splashStatus){
      var li = 0; splashStatus.textContent = splashLines[0];
      splashTimer = setInterval(function(){ li = (li + 1) % splashLines.length; splashStatus.textContent = splashLines[li]; }, 950);
    }
    if (i === 1 && keyType){
      var full = "FS-7K2P-9QXD-4MTA", shown = 4;
      keyType.textContent = full.slice(0, 4) + "-••••-••••-••••";
      keyTimer = setInterval(function(){
        shown += 2;
        if (shown >= full.length){ keyType.textContent = full; clearInterval(keyTimer); return; }
        keyType.textContent = full.slice(0, shown) + "•".repeat(Math.max(0, full.length - shown)).replace(/(.{4})(?=.)/g, "$1-");
      }, 160);
    }
  }
  function cycleScenes(){
    sceneTimer = setInterval(function(){ showScene((sceneIdx + 1) % scenes.length); }, 3400);
  }
  if (reduced){ showScene(2); }
  else { showScene(0); cycleScenes(); }

  /* ---------- interactive studio demo ---------- */
  var genBtn = document.getElementById("genBtn");
  var resetBtn = document.getElementById("resetBtn");
  var creditNum = document.getElementById("creditNum");
  var demoStatus = document.getElementById("demoStatus");
  var tiles = Array.prototype.slice.call(document.querySelectorAll("[data-tile]"));
  var CREDITS_START = 200, PER_VIDEO = 7;
  var credits = CREDITS_START, running = false, timers = [];

  function setCredits(v){
    credits = v; creditNum.textContent = v;
  }
  function later(fn, ms){ timers.push(setTimeout(fn, ms)); }
  function clearTimers(){ timers.forEach(clearTimeout); timers = []; }

  function setTile(tile, label, color, pct){
    var st = tile.querySelector("[data-stat]");
    var bar = tile.querySelector("[data-bar]");
    st.textContent = label; st.style.color = color;
    bar.style.width = pct + "%";
  }
  function resetDemo(){
    clearTimers(); running = false;
    genBtn.disabled = false;
    setCredits(CREDITS_START);
    tiles.forEach(function(t){
      t.classList.remove("working", "done");
      setTile(t, "Idle", "#8E88B8", 0);
    });
    demoStatus.textContent = "Ready — 3 prompts, 3 accounts, 21 credits planned.";
  }
  function runTile(tile, delay){
    later(function(){ tile.classList.add("working"); setTile(tile, "Queued", "#FFCE54", 8); }, delay);
    later(function(){ setTile(tile, "Generating", "#5ED6F2", 34); }, delay + 500);
    later(function(){ setTile(tile, "Generating", "#5ED6F2", 68); }, delay + 1500);
    later(function(){ setTile(tile, "Downloading", "#FF8FB5", 88); }, delay + 2300);
    later(function(){
      tile.classList.remove("working"); tile.classList.add("done");
      setTile(tile, "✓ Saved to Downloads", "#3ED598", 100);
    }, delay + 3000);
  }
  genBtn && genBtn.addEventListener("click", function(){
    if (running) return;
    running = true; genBtn.disabled = true;
    tiles.forEach(function(t){ t.classList.remove("done"); });
    demoStatus.textContent = "Planner split the batch across 3 accounts — generating in parallel…";
    tiles.forEach(function(t, i){ runTile(t, i * 450); });
    /* credits tick down 200 -> 179 as the three videos complete */
    var spent = 0;
    var cInt = setInterval(function(){
      spent += 1; setCredits(CREDITS_START - spent);
      if (spent >= PER_VIDEO * 3) clearInterval(cInt);
    }, 165);
    timers.push(cInt);
    later(function(){
      running = false; genBtn.disabled = false;
      demoStatus.textContent = "Done — 3 videos saved to Downloads · 21 credits used · 179 left.";
    }, 3000 + 2 * 450 + 350);
  });
  if (resetBtn){ resetBtn.addEventListener("click", resetDemo); }

  /* ---------- scroll progress bar + pill-tab indicator ---------- */
  var pBar = document.getElementById("progressBar");
  var tabTrack = document.getElementById("tabTrack");
  var tabIndicator = document.getElementById("tabIndicator");
  var navLinks = Array.prototype.slice.call(document.querySelectorAll("[data-nav]"));
  var currentTab = "home";
  function moveIndicator(link, keepScroll){
    if (!link || !tabIndicator) return;
    tabIndicator.style.opacity = "1";
    tabIndicator.style.left = link.offsetLeft + "px";
    tabIndicator.style.width = link.offsetWidth + "px";
    if (!keepScroll && tabTrack){
      var target = link.offsetLeft - (tabTrack.clientWidth - link.offsetWidth) / 2;
      tabTrack.scrollTo({ left: Math.max(0, target), behavior: reduced ? "auto" : "smooth" });
    }
  }
  function setActiveTab(name, keepScroll){
    var link = null;
    navLinks.forEach(function(a){
      var on = a.getAttribute("data-nav") === name;
      a.classList.toggle("active", on);
      if (on) link = a;
    });
    if (link){ currentTab = name; moveIndicator(link, keepScroll); }
  }
  navLinks.forEach(function(a){
    a.addEventListener("click", function(){ setActiveTab(a.getAttribute("data-nav"), false); });
  });
  var spyMap = [
    ["top","home"],["features","features"],["compare","compare"],["styles","features"],["how","features"],["samples","features"],["screenshots","features"],
    ["pricing","pricing"],["whatsnew","whatsnew"],["requirements","whatsnew"],
    ["tutorials","tutorials"],["support","tutorials"],["privacy","tutorials"],
    ["faq","faq"],["download","download"]
  ];
  function onScrollUI(){
    var h = document.documentElement;
    var max = h.scrollHeight - h.clientHeight;
    pBar.style.width = (max > 0 ? (h.scrollTop / max) * 100 : 0) + "%";
    var cur = "home";
    spyMap.forEach(function(pair){
      var el = document.getElementById(pair[0]);
      if (el && el.getBoundingClientRect().top <= 160) cur = pair[1];
    });
    if (cur !== currentTab) setActiveTab(cur, false);
  }
  window.addEventListener("scroll", onScrollUI, { passive: true });
  window.addEventListener("resize", function(){ setActiveTab(currentTab, true); });
  window.addEventListener("load", function(){ setActiveTab(currentTab, true); });
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(function(){ setActiveTab(currentTab, true); });
  setActiveTab("home", true);
  onScrollUI();

  /* ---------- button & tab style samples ---------- */
  document.querySelectorAll("[data-sample-tabs]").forEach(function(group){
    var card = group.closest(".style-card");
    var status = card ? card.querySelector("[data-sample-status]") : null;
    var label = card ? card.getAttribute("data-style-label") : "Style";
    group.querySelectorAll("button").forEach(function(btn){
      btn.addEventListener("click", function(){
        group.querySelectorAll("button").forEach(function(b){
          b.classList.remove("on"); b.setAttribute("aria-selected", "false");
        });
        btn.classList.add("on"); btn.setAttribute("aria-selected", "true");
        if (status) status.textContent = label + " · " + btn.textContent.trim() + " tab selected";
      });
    });
  });
  document.querySelectorAll("[data-sample-btn]").forEach(function(btn){
    btn.addEventListener("click", function(){
      var card = btn.closest(".style-card");
      var status = card ? card.querySelector("[data-sample-status]") : null;
      var label = card ? card.getAttribute("data-style-label") : "Style";
      if (status) status.textContent = label + " · \u201C" + btn.textContent.trim() + "\u201D pressed — sample only";
    });
  });

  /* ---------- FAQ accordions ---------- */
  document.querySelectorAll(".faq").forEach(function(faq){
    var btn = faq.querySelector("button");
    var ans = faq.querySelector(".ans");
    btn.addEventListener("click", function(){
      var open = faq.classList.contains("open");
      document.querySelectorAll(".faq.open").forEach(function(o){
        o.classList.remove("open");
        o.querySelector(".ans").style.maxHeight = "0px";
        o.querySelector("button").setAttribute("aria-expanded", "false");
      });
      if (!open){
        faq.classList.add("open");
        ans.style.maxHeight = ans.scrollHeight + "px";
        btn.setAttribute("aria-expanded", "true");
      }
    });
  });
})();
//

//
(function(){
  "use strict";
  var reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var PER_VIDEO = 7, PER_DAY = 50;
  var videos = 50, accounts = 10;
  var vGroup = document.getElementById("cmpVideos");
  var aGroup = document.getElementById("cmpAccts");
  var handBar = document.getElementById("cmpHandBar"), fsBar = document.getElementById("cmpFsBar");
  var handDay = document.getElementById("cmpHandDay"), fsDay = document.getElementById("cmpFsDay");
  var handMeta = document.getElementById("cmpHandMeta"), fsMeta = document.getElementById("cmpFsMeta");
  var verdict = document.getElementById("cmpVerdict");
  var runBtn = document.getElementById("cmpRun");
  var panel = document.getElementById("cmpDemo");
  if (!vGroup || !aGroup || !handBar || !fsBar || !runBtn) return;
  var rafs = [];

  function fmt(n){ return n.toLocaleString("en-US"); }
  function dayWord(d){ return d === 1 ? "1 day" : d + " days"; }

  function fill(bar, dayEl, days, dur){
    bar.style.transition = "none";
    bar.style.width = "0%";
    if (dur <= 0){
      bar.style.width = "100%";
      dayEl.textContent = "≈ " + dayWord(days);
      return;
    }
    dayEl.textContent = "Day 1 of " + days;
    void bar.offsetWidth;
    bar.style.transition = "width " + dur + "ms cubic-bezier(.25,.7,.3,1)";
    bar.style.width = "100%";
    var start = null;
    function step(ts){
      if (!start) start = ts;
      var p = Math.min((ts - start) / dur, 1);
      if (p >= 1){ dayEl.textContent = "≈ " + dayWord(days); return; }
      dayEl.textContent = "Day " + Math.max(1, Math.ceil(p * days)) + " of " + days;
      rafs.push(requestAnimationFrame(step));
    }
    rafs.push(requestAnimationFrame(step));
  }

  function run(){
    rafs.forEach(function(id){ cancelAnimationFrame(id); });
    rafs = [];
    var credits = videos * PER_VIDEO;
    var handDays = Math.ceil(credits / PER_DAY);
    var fsDays = Math.ceil(credits / (accounts * PER_DAY));
    var working = Math.min(accounts, Math.ceil(credits / PER_DAY));
    handMeta.textContent = fmt(credits) + " credits · one video at a time, waiting on a single account's daily credits";
    fsMeta.textContent = fmt(credits) + " credits planned before the run · " + working + (working === 1 ? " account" : " accounts") + " working in parallel · downloads save themselves";
    verdict.textContent = fsDays < handDays
      ? "Same batch: about " + dayWord(handDays) + " by hand → about " + dayWord(fsDays) + " with FlowStudio."
      : "Same days at this size — add more accounts and the gap opens up.";
    var handDur = reduced ? 0 : Math.min(5200, Math.max(750, handDays * 420));
    var fsDur = reduced ? 0 : Math.min(5200, Math.max(750, fsDays * 420));
    fill(handBar, handDay, handDays, handDur);
    fill(fsBar, fsDay, fsDays, fsDur);
  }

  function wire(group, attr, set){
    group.querySelectorAll("button").forEach(function(b){
      b.addEventListener("click", function(){
        group.querySelectorAll("button").forEach(function(x){
          x.classList.remove("on"); x.setAttribute("aria-pressed", "false");
        });
        b.classList.add("on"); b.setAttribute("aria-pressed", "true");
        set(parseInt(b.getAttribute(attr), 10));
        run();
      });
    });
  }
  wire(vGroup, "data-v", function(v){ videos = v; });
  wire(aGroup, "data-a", function(a){ accounts = a; });
  runBtn.addEventListener("click", run);

  /* play the race once when the demo first scrolls into view */
  if ("IntersectionObserver" in window && !reduced){
    var seen = false;
    var cio = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting && !seen){ seen = true; run(); cio.disconnect(); }
      });
    }, { threshold: 0.25 });
    cio.observe(panel);
  }
})();
//
